function AdminPartnerships() { const [selected, setSelected] = useState(null); const [exported, setExported] = useState(false); const [applications, setApplications] = useState([{id:'PA-204',name:'Amaka Okafor',pathway:'Strategic partnership',contribution:'₦500,000 - ₦2,000,000',date:'20 Aug 2026',status:'New',notes:'Interested in distribution partnerships.'},{id:'PA-203',name:'Dami Adeyemi',pathway:'Equipment partnership',contribution:'Commercial kitchen equipment',date:'14 Aug 2026',status:'Under review',notes:'Shared an equipment capability overview.'},{id:'PA-201',name:'Nneka James',pathway:'Business advisory partnership',contribution:'Operations and finance expertise',date:'02 Aug 2026',status:'Meeting scheduled',notes:'Follow-up conversation to be planned.'}]); const statuses=['New','Under review','Contacted','Meeting scheduled','Documentation pending','Closed']; const updateStatus = (value) => { setApplications((current) => current.map((item) => item.id === selected.id ? {...item,status:value} : item)); setSelected({...selected,status:value}); }; return <main className="admin-page"><aside className="admin-sidebar"><div className="wordmark">TCHOW<span>.</span></div><span className="admin-label">Operations preview</span><Link to="/admin">Overview</Link><Link to="/admin/orders">Orders</Link><Link to="/admin/menu">Menu</Link><Link to="/admin/catering">Catering</Link><Link to="/admin/investors" className="active">Partnerships</Link><Link to="/admin/settings">Settings</Link><Link to="/">Exit preview <ArrowRight size={14}/></Link></aside><div className="admin-workspace"><header className="admin-topbar"><div><span className="eyebrow">Internal operations</span><strong>Partnership Applications</strong></div><span className="mock-pill">Mock data</span></header><div className="admin-content"><div className="admin-banner"><span className="eyebrow">Frontend-only internal preview</span><strong>Mock data only</strong></div><Intro eyebrow="Partnership Applications" title="Review interest responsibly.">Review preliminary interest and keep conversations organized. No money is accepted and no investment is confirmed here.</Intro><div className="partnership-toolbar"><span>{applications.length} mock applications</span><Button variant="outline" onClick={() => setExported(true)}>Export preview <ArrowRight size={15}/></Button>{exported && <small role="status">Export preview prepared locally.</small>}</div><div className="partnership-table"><div className="partnership-head"><span>Applicant</span><span>Pathway</span><span>Contribution</span><span>Submitted</span><span>Status</span><span></span></div>{applications.map((item) => <div className="partnership-row" key={item.id}><span><strong>{item.name}</strong><small>{item.id}</small></span><span>{item.pathway}</span><span>{item.contribution}</span><span>{item.date}</span><span className="status-badge">{item.status}</span><button className="button button-outline" onClick={() => setSelected(item)}>View application</button></div>)}</div></div></div>{selected && <div className="drawer-overlay" onClick={() => setSelected(null)}><aside className="order-drawer admin-enquiry-drawer" role="dialog" aria-modal="true" aria-labelledby="partnership-title" onClick={(e) => e.stopPropagation()}><button className="drawer-close" onClick={() => setSelected(null)} aria-label="Close application details"><X size={20}/></button><span className="eyebrow">Partnership application</span><h2 id="partnership-title">{selected.id}</h2><div className="drawer-details"><div><span>Applicant</span><strong>{selected.name}</strong></div><div><span>Pathway</span><strong>{selected.pathway}</strong></div><div><span>Contribution</span><strong>{selected.contribution}</strong></div><div><span>Submission date</span><strong>{selected.date}</strong></div></div><label className="status-update">Review status<select value={selected.status} onChange={(e) => updateStatus(e.target.value)}>{statuses.map((item) => <option key={item}>{item}</option>)}</select></label><label className="internal-notes">Internal notes<textarea rows="6" defaultValue={selected.notes} placeholder="Add a private review note"/></label><Button variant="outline" onClick={() => setSelected(null)}>Save local changes <Check size={16}/></Button><p className="summary-note">Preliminary interest only. This preview does not accept money or confirm an investment.</p></aside></div>}</main>; }

function AdminCatering() { const [selected, setSelected] = useState(null); const [enquiries, setEnquiries] = useState([{id:'CE-1042',name:'Amaka Okafor',event:'Corporate breakfast',date:'24 Aug 2026',guests:'32 guests',location:'Victoria Island, Lagos',status:'New',notes:'Looking for a light breakfast spread before a 9am meeting.'},{id:'CE-1041',name:'Dami Adeyemi',event:'Birthday events',date:'31 Aug 2026',guests:'50 guests',location:'Lekki Phase 1, Lagos',status:'Reviewing',notes:'Small chops and drinks. Please include vegetarian options.'},{id:'CE-1039',name:'Nneka James',event:'Brand activations',date:'12 Sep 2026',guests:'120 guests',location:'Ikeja, Lagos',status:'Quoted',notes:'Branded packaging discussion required.'},{id:'CE-1036',name:'Bola Williams',event:'Private brunches',date:'18 Jul 2026',guests:'12 guests',location:'Yaba, Lagos',status:'Confirmed',notes:'Morning delivery requested.'}]); const statuses=['New','Reviewing','Contacted','Quoted','Confirmed','Closed']; const updateStatus = (value) => { setEnquiries((current) => current.map((item) => item.id === selected.id ? {...item,status:value} : item)); setSelected({...selected,status:value}); }; return <main className="admin-page"><aside className="admin-sidebar"><div className="wordmark">TCHOW<span>.</span></div><span className="admin-label">Operations preview</span><Link to="/admin">Overview</Link><Link to="/admin/orders">Orders</Link><Link to="/admin/menu">Menu</Link><Link to="/admin/catering" className="active">Catering</Link><Link to="/admin/investors">Partnerships</Link><Link to="/admin/settings">Settings</Link><Link to="/">Exit preview <ArrowRight size={14}/></Link></aside><div className="admin-workspace"><header className="admin-topbar"><div><span className="eyebrow">Internal operations</span><strong>Catering enquiries</strong></div><span className="mock-pill">Mock data</span></header><div className="admin-content"><div className="admin-banner"><span className="eyebrow">Frontend-only internal preview</span><strong>Mock data only</strong></div><Intro eyebrow="Catering enquiries" title="Plan the next great table.">Review event details and manage local preview statuses. No enquiry is sent to a backend.</Intro><div className="enquiry-summary"><span>{enquiries.length} open enquiries</span><span>{enquiries.filter((x) => x.status === 'New').length} new today</span></div><div className="enquiry-table"><div className="enquiry-head"><span>Enquiry</span><span>Event type</span><span>Date</span><span>Guests</span><span>Location</span><span>Status</span><span></span></div>{enquiries.map((item) => <div className="enquiry-row" key={item.id}><span><strong>{item.id}</strong><small>{item.name}</small></span><span>{item.event}</span><span>{item.date}</span><span>{item.guests}</span><span>{item.location}</span><span className="status-badge">{item.status}</span><button className="button button-outline" onClick={() => setSelected(item)}>View details</button></div>)}</div></div></div>{selected && <div className="drawer-overlay" onClick={() => setSelected(null)}><aside className="order-drawer admin-enquiry-drawer" role="dialog" aria-modal="true" aria-labelledby="enquiry-title" onClick={(e) => e.stopPropagation()}><button className="drawer-close" onClick={() => setSelected(null)} aria-label="Close enquiry details"><X size={20}/></button><span className="eyebrow">Catering enquiry</span><h2 id="enquiry-title">{selected.id}</h2><div className="drawer-details"><div><span>Customer</span><strong>{selected.name}</strong></div><div><span>Event</span><strong>{selected.event}</strong></div><div><span>Date and guests</span><strong>{selected.date}<br/>{selected.guests}</strong></div><div><span>Location</span><strong>{selected.location}</strong></div></div><label className="status-update">Enquiry status<select value={selected.status} onChange={(e) => updateStatus(e.target.value)}>{statuses.map((item) => <option key={item}>{item}</option>)}</select></label><label className="internal-notes">Internal notes<textarea rows="6" defaultValue={selected.notes} placeholder="Add a private operations note"/></label><Button onClick={() => setSelected(null)}>Save local changes <Check size={16}/></Button><p className="summary-note">This enquiry and its status are mock preview data only.</p></aside></div>}</main>; }

function AdminMenu() { const [products, setProducts] = useState(() => store('tchow-admin-menu', MENU_ITEMS.slice(0, 12).map((item) => ({...item, available:true})))); const [query, setQuery] = useState(''); const [category, setCategory] = useState('All categories'); const [editing, setEditing] = useState(null); const [preview, setPreview] = useState(null); const [deleting, setDeleting] = useState(null); useEffect(() => localStorage.setItem('tchow-admin-menu', JSON.stringify(products)), [products]); const visible = products.filter((item) => `${item.name} ${item.description} ${item.tag}`.toLowerCase().includes(query.toLowerCase()) && (category === 'All categories' || item.category === category)); const toggle = (id) => setProducts((current) => current.map((item) => item.id === id ? {...item, available:!item.available} : item)); const save = (event) => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget)); const next = {...editing, ...data, price:Number(data.price), available:editing.available ?? true}; setProducts((current) => editing.id ? current.map((item) => item.id === editing.id ? next : item) : [{...next,id:`mock-${Date.now()}`,image:'/assets/hero.jpg',tag:data.tag || 'New'}, ...current]); setEditing(null); }; return <main className="admin-page"><aside className="admin-sidebar"><div className="wordmark">TCHOW<span>.</span></div><span className="admin-label">Operations preview</span><Link to="/admin">Overview</Link><Link to="/admin/orders">Orders</Link><Link to="/admin/menu" className="active">Menu</Link><Link to="/admin/catering">Catering</Link><Link to="/admin/investors">Partnerships</Link><Link to="/admin/settings">Settings</Link><Link to="/">Exit preview <ArrowRight size={14}/></Link></aside><div className="admin-workspace"><header className="admin-topbar"><div><span className="eyebrow">Internal operations</span><strong>Menu management</strong></div><span className="mock-pill">Mock data</span></header><div className="admin-content"><div className="admin-banner"><span className="eyebrow">Frontend-only internal preview</span><strong>Mock data only</strong></div><Intro eyebrow="Menu management" title="Keep the catalogue current.">Edit mock products and availability locally. No changes are sent to a backend.</Intro><div className="menu-admin-toolbar"><label className="search-field"><Search size={17}/><input placeholder="Search products" value={query} onChange={(e) => setQuery(e.target.value)}/></label><select value={category} onChange={(e) => setCategory(e.target.value)} aria-label="Filter products by category"><option>All categories</option>{MENU_CATEGORIES.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select><Button onClick={() => setEditing({name:'',category:'signature',description:'',price:0,prepTime:'15 mins',tag:'New',available:true})}>Add product <Plus size={16}/></Button></div><div className="menu-table"><div className="menu-table-head"><span>Product</span><span>Category</span><span>Price</span><span>Prep</span><span>Availability</span><span>Actions</span></div>{visible.map((item) => <div className="menu-table-row" key={item.id}><span className="menu-product"><img src={item.image} alt=""/><strong>{item.name}</strong></span><span>{MENU_CATEGORIES.find((x) => x.id === item.category)?.label || item.category}</span><span>{money(item.price)}</span><span>{item.prepTime}</span><button className={`availability-toggle ${item.available ? 'is-available' : ''}`} onClick={() => toggle(item.id)} aria-pressed={item.available}>{item.available ? 'Available' : 'Unavailable'}</button><span className="menu-actions"><button onClick={() => setEditing(item)} aria-label={`Edit ${item.name}`}><Plus size={14}/> Edit</button><button onClick={() => setPreview(item)}>Preview</button><button className="danger-action" onClick={() => setDeleting(item)}>Delete</button></span></div>)}{!visible.length && <div className="empty-state"><Search size={28}/><h3>No products found.</h3></div>}</div></div></div>{editing && <div className="drawer-overlay"><aside className="order-drawer menu-editor" role="dialog" aria-modal="true"><button className="drawer-close" onClick={() => setEditing(null)} aria-label="Close product editor"><X size={20}/></button><span className="eyebrow">{editing.id ? 'Edit product' : 'Add product'}</span><h2>{editing.id ? 'Edit product' : 'New product'}</h2><form className="admin-edit-form" onSubmit={save}><label>Name<input required name="name" defaultValue={editing.name}/></label><label>Category<select name="category" defaultValue={editing.category}>{MENU_CATEGORIES.map((item) => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label><label>Description<textarea required rows="4" name="description" defaultValue={editing.description}/></label><label>Price<input required type="number" name="price" defaultValue={editing.price}/></label><label>Preparation time<input required name="prepTime" defaultValue={editing.prepTime}/></label><label>Tags<input name="tag" defaultValue={editing.tag}/></label><Button type="submit">Save locally <Check size={16}/></Button></form></aside></div>}{preview && <div className="drawer-overlay" onClick={() => setPreview(null)}><aside className="order-drawer menu-preview" role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}><button className="drawer-close" onClick={() => setPreview(null)} aria-label="Close product preview"><X size={20}/></button><img src={preview.image} alt={preview.name}/><span className="eyebrow">Product preview</span><h2>{preview.name}</h2><strong>{money(preview.price)}</strong><p>{preview.description}</p><span className={`status-badge ${preview.available ? 'status-completed' : 'status-cancelled'}`}>{preview.available ? 'Available' : 'Unavailable'}</span></aside></div>}{deleting && <div className="modal-backdrop"><div className="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="delete-title"><span className="eyebrow">Delete product</span><h2 id="delete-title">Remove {deleting.name}?</h2><p>This only removes the product from local mock state.</p><div><Button variant="outline" onClick={() => setDeleting(null)}>Cancel</Button><Button onClick={() => { setProducts((current) => current.filter((item) => item.id !== deleting.id)); setDeleting(null); }}>Delete locally</Button></div></div></div>}</main>; }

function AdminOrders() { const [query, setQuery] = useState(''); const [status, setStatus] = useState('All statuses'); const [date, setDate] = useState('All dates'); const [selected, setSelected] = useState(null); const [orders, setOrders] = useState([{id:'TC-42108',customer:'Amaka Okafor',items:'2 × The Tchow Box',total:13000,date:'Today',payment:'Coming soon',fulfilment:'Received for review',notes:'Please call on arrival.'},{id:'TC-42107',customer:'Dami Adeyemi',items:'Weekend Bliss Breakfast Platter',total:8500,date:'Today',payment:'Coming soon',fulfilment:'Preparing',notes:'Office reception desk.'},{id:'TC-42091',customer:'Nneka James',items:'Classic Party Pack · 40 pieces',total:14000,date:'Yesterday',payment:'Coming soon',fulfilment:'Ready for dispatch',notes:'Birthday gathering.'},{id:'TC-42044',customer:'Bola Williams',items:'Parfait Royale · 2',total:8000,date:'21 Jul 2026',payment:'Coming soon',fulfilment:'Completed',notes:'Leave with concierge.'}]); const statuses = ['All statuses','Received for review','Preparing','Ready for dispatch','Completed']; const filtered = orders.filter((order) => `${order.id} ${order.customer} ${order.items}`.toLowerCase().includes(query.toLowerCase()) && (status === 'All statuses' || order.fulfilment === status) && (date === 'All dates' || order.date === date)); const updateStatus = (next) => { setOrders((current) => current.map((order) => order.id === selected.id ? {...order, fulfilment: next} : order)); setSelected({...selected, fulfilment: next}); }; return <main className="admin-page"><aside className="admin-sidebar"><div className="wordmark">TCHOW<span>.</span></div><span className="admin-label">Operations preview</span><Link to="/admin">Overview</Link><Link to="/admin/orders" className="active">Orders</Link><Link to="/admin/menu">Menu</Link><Link to="/admin/catering">Catering</Link><Link to="/admin/investors">Partnerships</Link><Link to="/admin/settings">Settings</Link><Link to="/">Exit preview <ArrowRight size={14}/></Link></aside><div className="admin-workspace"><header className="admin-topbar"><div><span className="eyebrow">Internal operations</span><strong>Order management</strong></div><span className="mock-pill">Mock data</span></header><div className="admin-content"><div className="admin-banner"><span className="eyebrow">Frontend-only internal preview</span><strong>Mock data only</strong></div><Intro eyebrow="Order management" title="Keep every order moving.">Search and review local mock orders. No payment or fulfilment workflow is connected.</Intro><div className="orders-toolbar"><label className="search-field"><Search size={17}/><input placeholder="Search customer, order or item" value={query} onChange={(e) => setQuery(e.target.value)}/></label><select value={status} onChange={(e) => setStatus(e.target.value)} aria-label="Filter by fulfilment status">{statuses.map((item) => <option key={item}>{item}</option>)}</select><select value={date} onChange={(e) => setDate(e.target.value)} aria-label="Filter by date"><option>All dates</option><option>Today</option><option>Yesterday</option><option>21 Jul 2026</option></select></div><div className="orders-table"><div className="orders-table-head"><span>Order</span><span>Customer</span><span>Items</span><span>Total</span><span>Payment</span><span>Fulfilment</span><span></span></div>{filtered.map((order) => <div className="orders-table-row" key={order.id}><span><strong>{order.id}</strong><small>{order.date}</small></span><span>{order.customer}</span><span>{order.items}</span><strong>{money(order.total)}</strong><span className="muted">{order.payment}</span><span className="status-badge">{order.fulfilment}</span><button className="button button-outline" onClick={() => setSelected(order)}>View order</button></div>)}{!filtered.length && <div className="empty-state"><Search size={28}/><h3>No orders match these filters.</h3><p>Try clearing the search or choosing another status.</p></div>}</div></div></div>{selected && <div className="drawer-overlay" onClick={() => setSelected(null)}><aside className="order-drawer admin-order-drawer" role="dialog" aria-modal="true" aria-labelledby="admin-order-title" onClick={(e) => e.stopPropagation()}><button className="drawer-close" onClick={() => setSelected(null)} aria-label="Close order details"><X size={20}/></button><span className="eyebrow">Order detail</span><h2 id="admin-order-title">{selected.id}</h2><span className="status-badge">{selected.fulfilment}</span><div className="drawer-details"><div><span>Customer</span><strong>{selected.customer}</strong></div><div><span>Delivery</span><strong>Lagos, Nigeria<br/>{selected.notes}</strong></div><div><span>Items</span><strong>{selected.items}</strong></div><div><span>Total</span><strong>{money(selected.total)}</strong></div><div><span>Payment</span><strong>{selected.payment}</strong></div></div><h3 className="drawer-subtitle">Status timeline</h3><div className="status-timeline"><span>Order details recorded</span><span className="current">{selected.fulfilment}</span><span>Fulfilment update pending</span></div><label className="status-update">Update fulfilment status<select value={selected.fulfilment} onChange={(e) => updateStatus(e.target.value)}>{statuses.slice(1).map((item) => <option key={item}>{item}</option>)}</select></label><p className="summary-note">Status updates are local preview state only.</p></aside></div>}</main>; }

function FAQPage() {
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState('ordering-0');
  const groups = [
    ['Ordering', [['How far ahead should I order?', 'We recommend ordering at least a day ahead for larger or weekend orders.'], ['How do I know my order details were saved?', 'The confirmation screen shows your locally recorded order number and summary.']]],
    ['Delivery', [['Do you deliver?', 'Delivery details and available slots are shown at checkout in this frontend preview.'], ['Can I include delivery instructions?', 'Yes. Add landmarks, gate details or timing notes in the checkout delivery instructions field.']]],
    ['Custom boxes', [['Can I customise a box?', 'Build Your Box lets you choose the base size, savoury bite, drink and dessert.'], ['Can I change my box later?', 'Your unfinished builder progress is saved locally while you decide.']]],
    ['Catering', [['Do you offer catering for offices?', 'Yes. We create thoughtful spreads for office meetings, corporate breakfasts and brand activations.'], ['How far ahead should I enquire?', 'For larger events, two to four weeks gives us the best room to plan.']]],
    ['Payments', [['How do payments work?', 'Payment methods are currently a preview only. No payment is processed until connected checkout is implemented.'], ['Can I pay by WhatsApp?', 'WhatsApp confirmation is shown as a coming-soon option and is not connected yet.']]],
    ['Dietary requirements', [['Do you have dietary options?', 'Tell us about your needs in an enquiry and we will explore suitable options with you.'], ['Where can I share dietary notes?', 'Use the product notes or contact form to describe the requirement clearly.']]],
    ['Partnership enquiries', [['How can I discuss a partnership?', 'Visit the partnership application to choose a pathway and share a little about what you bring.'], ['Is this an investment offer?', 'No. The Investor Relations page is for preliminary partnership interest only and is not a public offer or guarantee.']]],
  ];
  const matches = groups.map(([name, items]) => [name, items.filter(([question, answer]) => `${name} ${question} ${answer}`.toLowerCase().includes(query.toLowerCase()))]).filter(([, items]) => items.length);
  return <main className="page faq-page"><Intro eyebrow="Frequently asked questions" title="Questions, answered simply.">Ordering, delivery, custom boxes and partnerships. Search the answers below or contact the Tchow concierge.</Intro><label className="faq-search"><Search size={18}/><input aria-label="Search FAQs" placeholder="Search questions and answers" value={query} onChange={(e) => setQuery(e.target.value)}/></label>{matches.length ? <div className="faq-groups">{matches.map(([name, items]) => <section className="faq-group" key={name}><span className="eyebrow">{name}</span>{items.map(([question, answer], index) => { const id = `${name.toLowerCase().replaceAll(' ', '-')}-${index}`; const isOpen = open === id; return <div className={`faq ${isOpen ? 'open' : ''}`} key={question}><button aria-expanded={isOpen} aria-controls={`${id}-panel`} onClick={() => setOpen(isOpen ? '' : id)}>{question}<ChevronDown size={18}/></button>{isOpen && <p id={`${id}-panel`}>{answer}</p>}</div>; })}</section>)}</div> : <div className="faq-empty"><Search size={28}/><h2>Can’t find your answer?</h2><p>Contact the Tchow concierge and we will help you find the right next step.</p><Button to="/contact">Contact the Tchow concierge <ArrowRight size={16}/></Button></div>}</main>;
}

function Info({ kind }) { return kind === 'faq' ? <FAQPage/> : null; }

const money = (n) => `₦${n.toLocaleString('en-NG')}`;
const store = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) || fallback; } catch { return fallback; } };

function useRouter() {
  const [path, setPath] = useState(location.pathname + location.search);
  useEffect(() => { const fn = () => setPath(location.pathname + location.search); addEventListener('popstate', fn); return () => removeEventListener('popstate', fn); }, []);
  return (to) => { history.pushState({}, '', to); setPath(to); scrollTo({ top: 0, behavior: 'smooth' }); };
}
function Link({ to, children, className = '', onClick }) { return <a href={to} className={className} onClick={(e) => { e.preventDefault(); onClick?.(); history.pushState({}, '', to); dispatchEvent(new PopStateEvent('popstate')); scrollTo({ top: 0, behavior: 'smooth' }); }}>{children}</a>; }
function Button({ to, children, variant = 'primary', onClick, type = 'button' }) { return to ? <Link to={to} className={`button button-${variant}`}>{children}</Link> : <button type={type} className={`button button-${variant}`} onClick={onClick}>{children}</button>; }
function Intro({ eyebrow, title, children }) { return <div className="page-intro"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{children && <p>{children}</p>}</div>; }

function Header({ count }) { const [open, setOpen] = useState(false); const [notice, setNotice] = useState(true); const links = [['/menu', 'Menu'], ['/build-your-box', 'Build a box'], ['/catering', 'Catering'], ['/about', 'About'], ['/investors', 'Investor Relations'], ['/contact', 'Contact']]; return <>{notice && <div className="announcement"><strong>Weekend breakfast orders are open</strong><span>Pre-order early for priority dispatch.</span><button onClick={() => setNotice(false)} aria-label="Dismiss announcement"><X size={13}/></button></div>}<header className="site-header"><div className="nav-wrap"><Link to="/" className="wordmark">TCHOW<span>.</span></Link><nav className="desktop-nav">{links.map(([to, label]) => <Link to={to} key={to}>{label}</Link>)}</nav><div className="nav-actions"><Link to="/account" className="account-link">Account</Link><Link to="/cart" className="cart-button" aria-label="Cart"><ShoppingBag size={18}/><span>{count}</span></Link><button className="mobile-menu" onClick={() => setOpen(true)} aria-label="Open menu"><MenuIcon size={22}/></button></div></div></header>{open && <div className="mobile-panel"><div className="mobile-panel-head"><span className="wordmark">TCHOW<span>.</span></span><button onClick={() => setOpen(false)} aria-label="Close menu"><X/></button></div>{links.map(([to, label]) => <Link to={to} key={to} onClick={() => setOpen(false)}>{label}<ArrowRight size={16}/></Link>)}<Link to="/cart" className="mobile-cart" onClick={() => setOpen(false)}>View cart <span>{count} items</span></Link></div>}</>; }
function Footer() { return <footer className="footer"><div className="footer-grid"><div><div className="wordmark">TCHOW<span>.</span></div><p>Food experiences made memorable. Prepared with care in Lagos.</p><a href="mailto:hello@tchow.ng">hello@tchow.ng</a><div className="social-placeholders"><span>Instagram</span><span>Facebook</span><span>LinkedIn</span></div></div><div><h4>Explore</h4><Link to="/menu">Menu</Link><Link to="/build-your-box">Build your box</Link><Link to="/catering">Catering</Link><Link to="/about">Our story</Link></div><div><h4>Support</h4><Link to="/faq">FAQs</Link><Link to="/contact">Contact</Link><Link to="/account">Your account</Link><Link to="/privacy">Privacy</Link></div><div><h4>For business</h4><Link to="/investors">Partnerships</Link><Link to="/investors/apply">Submit interest</Link><Link to="/admin">Operations preview</Link><Link to="/terms">Terms</Link><small>Frontend preview. Payments and fulfilment are not connected yet.</small></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} Tchow. All rights reserved.</span><span>Lagos, Nigeria</span></div></footer>; }
function ProductCard({ item, add }) { const category = MENU_CATEGORIES.find((c) => c.id === item.category)?.label.split(' (')[0]; return <article className="product-card"><Link to={`/menu/${item.id}`} className="product-image"><img src={item.image} alt={item.name}/><span className="product-tag">{item.tag}</span></Link><div className="product-copy"><div className="product-meta"><span>{category}</span><span><Clock3 size={13}/> {item.prepTime}</span></div><Link to={`/menu/${item.id}`}><h3>{item.name}</h3></Link><p>{item.description}</p><div className="product-footer"><strong>{money(item.price)}</strong><button className="add-button" onClick={() => add(item)}><Plus size={17}/> Add</button></div></div></article>; }

function Home({ add }) { const featured = MENU_ITEMS.slice(0, 4); const principles = [['01', 'Freshly prepared', 'Small-batch cooking, made with ingredients we are proud of.'], ['02', 'Thoughtfully curated', 'Flavours and textures that make every bite feel considered.'], ['03', 'Beautifully presented', 'Because the first taste is always with the eyes.'], ['04', 'Delivered with care', 'Packed beautifully and communicated clearly, every time.']]; return <main className="home"><section className="hero"><div className="hero-copy"><span className="eyebrow">The Tchow table</span><h1>Food experiences made <em>memorable.</em></h1><p>Curated breakfasts, artisanal small chops, desserts and refreshing drinks prepared for everyday moments, celebrations and meaningful connections.</p><div className="hero-buttons"><Button to="/menu">Explore the menu <ArrowRight size={17}/></Button><Button to="/build-your-box" variant="outline">Build your box</Button></div><div className="hero-proof"><span><strong>Freshly prepared</strong> in small batches</span><span><strong>Lagos-made</strong> with a lot of heart</span></div></div><div className="hero-art"><img src="/assets/hero.jpg" alt="A colourful spread of Tchow breakfast and small chops"/><div className="hero-sticker"><Sparkles size={15}/> Made for sharing</div><div className="hero-caption"><span>01 / 04</span><strong>A little joy,<br/>boxed.</strong></div></div></section><section className="section"><div className="section-heading"><div><span className="eyebrow">From the kitchen</span><h2>What are you in the mood for?</h2></div><Link to="/menu" className="text-link">See the full menu <ArrowRight size={16}/></Link></div><div className="product-grid">{featured.map((item) => <ProductCard key={item.id} item={item} add={add}/>)}</div></section><section className="experience-band"><div><span className="eyebrow">The Tchow way</span><h2>Good food is a<br/><em>love language.</em></h2></div><div className="principles">{principles.map(([n, title, copy]) => <div className="principle" key={n}><span>{n}</span><h3>{title}</h3><p>{copy}</p></div>)}</div></section><section className="box-feature"><div className="box-photo"><img src="/assets/small_chops.jpg" alt="A Tchow box filled with assorted small chops"/><span>Your table, your rules</span></div><div className="box-copy"><span className="eyebrow">A box for every kind of day</span><h2>Make it yours.</h2><p>Choose the size, pick your favourites, add a drink and finish with something sweet. Your perfect Tchow moment, assembled by you.</p><Button to="/build-your-box">Create your box <ArrowRight size={17}/></Button><div className="box-price"><span>From</span><strong>₦4,500</strong></div></div></section><section className="section category-section"><div className="section-heading"><div><span className="eyebrow">Pick your pleasure</span><h2>Something for every table.</h2></div></div><div className="category-grid">{MENU_CATEGORIES.slice(1, 7).map((cat, i) => <Link key={cat.id} to={`/menu?category=${cat.id}`} className={`category-tile category-${i + 1}`}><span>0{i + 1}</span><h3>{cat.label.replace(' (Weekends)', '').replace(' & Warm Brews', '')}</h3><ArrowRight size={18}/></Link>)}</div></section><section className="split-cta"><div><span className="eyebrow">Gather well</span><h2>Let us handle<br/><em>the spread.</em></h2><p>Corporate breakfasts, birthdays, private brunches and brand moments. Tell us what you are planning and we will shape the table around it.</p><Button to="/catering">Plan your catering <ArrowRight size={17}/></Button></div><img src="/assets/pancakes.jpg" alt="Tchow breakfast platter prepared for sharing"/></section><section className="trust-strip"><div><Heart size={20}/><strong>Made with care</strong><span>Quality ingredients, considered presentation.</span></div><div><Package size={20}/><strong>Clear communication</strong><span>From order confirmation to delivery details.</span></div><div><Sparkles size={20}/><strong>Worth remembering</strong><span>Food that turns ordinary moments into stories.</span></div></section></main>; }

function HomePage({ add }) { const [notice, setNotice] = useState(true); const featured = MENU_ITEMS.slice(0, 4); const categories = [['breakfast','Breakfast','/assets/pancakes.jpg'],['chops','Small Chops','/assets/small_chops.jpg'],['desserts','Desserts','/assets/desserts.jpg'],['specialty','Drinks','/assets/beverages.jpg'],['party-packs','Party Packs','/assets/hero.jpg'],['coffee','Coffee','/assets/hero.jpg']]; const faqs = ['How far ahead should I order?','Do you offer catering for offices?','Can I customise a box?','How do payments work?']; return <main className="home">{notice && <div className="home-notice"><span>Weekend breakfast orders are open. Pre-order early for priority dispatch.</span><button onClick={() => setNotice(false)} aria-label="Dismiss announcement"><X size={15}/></button></div>}<section className="hero"><div className="hero-copy"><span className="eyebrow">The Tchow table</span><h1>Food experiences made <em>memorable.</em></h1><p>Curated breakfasts, artisanal small chops, desserts, and refreshing drinks prepared for everyday moments, celebrations, and meaningful connections.</p><div className="hero-buttons"><Button to="/menu">Explore the menu <ArrowRight size={17}/></Button><Button to="/build-your-box" variant="outline">Build your box</Button></div></div><div className="hero-art"><img src="/assets/hero.jpg" alt="A premium spread of Tchow breakfast and small chops"/><div className="hero-sticker"><Sparkles size={15}/> Made for sharing</div></div></section><section className="section"><div className="section-heading"><div><span className="eyebrow">From the kitchen</span><h2>What are you in the mood for?</h2></div><Link to="/menu" className="text-link">See the full menu <ArrowRight size={16}/></Link></div><div className="product-grid">{featured.map((item) => <article className="product-card" key={item.id}><Link to={`/menu/${item.id}`} className="product-image"><img src={item.image} alt={item.name}/><span className="product-tag">{item.tag}</span></Link><div className="product-copy"><div className="product-meta"><span>{MENU_CATEGORIES.find((c) => c.id === item.category)?.label.split(' (')[0]}</span><span><Clock3 size={13}/> {item.prepTime}</span></div><h3>{item.name}</h3><p>{item.description}</p><div className="product-footer"><strong>{money(item.price)}</strong><div className="featured-actions"><Link to={`/menu/${item.id}`} className="text-link">View product</Link><button className="add-button" onClick={() => add(item)}><Plus size={17}/> Add</button></div></div></div></article>)}</div></section><section className="experience-band"><div><span className="eyebrow">The Tchow way</span><h2>Good food is a<br/><em>love language.</em></h2></div><div className="principles">{[['01','Freshly prepared','Small-batch cooking, made with ingredients we are proud of.'],['02','Thoughtfully curated','Flavours and textures that make every bite feel considered.'],['03','Beautifully presented','Because the first taste is always with the eyes.'],['04','Delivered with care','Packed beautifully and communicated clearly, every time.']].map(([n,title,copy]) => <div className="principle" key={n}><span>{n}</span><h3>{title}</h3><p>{copy}</p></div>)}</div></section><section className="box-feature"><div className="box-photo"><img src="/assets/small_chops.jpg" alt="A Tchow custom food box filled with assorted small chops"/><span>Your table, your rules</span></div><div className="box-copy"><span className="eyebrow">A box for every kind of day</span><h2>Make it yours.</h2><p>Choose the size, pick your favourites, add a drink and finish with something sweet. Your perfect Tchow moment, assembled by you.</p><Button to="/build-your-box">Create your box <ArrowRight size={17}/></Button></div></section><section className="section category-section"><div className="section-heading"><div><span className="eyebrow">Pick your pleasure</span><h2>Something for every table.</h2></div></div><div className="category-grid">{categories.map(([id,label,image],i) => <Link key={id} to={`/menu?category=${id}`} className={`category-tile category-${i+1}`}><img src={image} alt=""/><span>0{i+1}</span><h3>{label}</h3><ArrowRight size={18}/></Link>)}</div></section><section className="split-cta"><div><span className="eyebrow">Corporate and private events</span><h2>Let us handle<br/><em>the spread.</em></h2><p>Corporate breakfasts, office meetings, birthdays, private events, and brand activations. Tell us what you are planning and we will shape the table around it.</p><Button to="/catering">Plan your catering <ArrowRight size={17}/></Button></div><img src="/assets/pancakes.jpg" alt="Tchow breakfast platter prepared for a private event"/></section><section className="trust-strip"><div><Heart size={20}/><strong>Order confirmation support</strong><span>Clear next steps from order to table.</span></div><div><Package size={20}/><strong>Flexible catering arrangements</strong><span>Thoughtful options for different gatherings.</span></div><div><Sparkles size={20}/><strong>Clear communication</strong><span>Useful details, shared at the right time.</span></div><div><Heart size={20}/><strong>Carefully packaged food</strong><span>Beautifully prepared for the journey.</span></div></section><section className="home-investor"><div><span className="eyebrow">For thoughtful partners</span><h2>A considered opportunity is taking shape.</h2><p>Explore Tchow's product model, growth phases, and responsible partnership pathways.</p></div><Button to="/investors" variant="outline">Explore strategic partnerships <ArrowRight size={17}/></Button></section><section className="home-faq section"><div className="section-heading"><div><span className="eyebrow">A few answers</span><h2>Good to know.</h2></div><Link to="/faq" className="text-link">See all FAQs <ArrowRight size={16}/></Link></div><div className="faq-preview">{faqs.map((question) => <Link key={question} to="/faq"><span>{question}</span><ArrowRight size={16}/></Link>)}</div></section></main>; }

function Menu({ add }) { const params = new URLSearchParams(location.search); const [query, setQuery] = useState(''); const [category, setCategory] = useState(params.get('category') || 'all'); const [sort, setSort] = useState('featured'); const [loading, setLoading] = useState(false); const filtered = useMemo(() => { const list = MENU_ITEMS.filter((x) => (category === 'all' || x.category === category) && `${x.name} ${x.description}`.toLowerCase().includes(query.toLowerCase())); return sort === 'low' ? [...list].sort((a,b) => a.price-b.price) : sort === 'high' ? [...list].sort((a,b) => b.price-a.price) : list; }, [category, query, sort]); const choose = (value) => { setLoading(true); setCategory(value); setTimeout(() => setLoading(false), 240); }; return <main className="page"><Intro eyebrow="The menu" title="Find your next favourite.">From slow weekend breakfasts to a box of golden small chops, everything is made to order and ready for your kind of gathering.</Intro><section className="catalog"><div className="catalog-toolbar"><label className="search-field"><Search size={18}/><input placeholder="Search the menu" value={query} onChange={(e) => setQuery(e.target.value)}/></label><select value={sort} onChange={(e) => setSort(e.target.value)} aria-label="Sort menu"><option value="featured">Featured first</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></div><div className="category-tabs"><button className={category === 'all' ? 'active' : ''} onClick={() => choose('all')}>All plates</button>{MENU_CATEGORIES.map((cat) => <button key={cat.id} className={category === cat.id ? 'active' : ''} onClick={() => choose(cat.id)}>{cat.label.split(' (')[0]}</button>)}</div><div className="catalog-count"><span>{loading ? 'Finding something delicious...' : `${filtered.length} things worth sharing`}</span><span>Prices in Nigerian naira</span></div>{loading ? <div className="loading-state">Preparing the menu <span>•••</span></div> : filtered.length ? <div className="product-grid catalog-grid">{filtered.map((item) => <ProductCard key={item.id} item={item} add={add}/>)}</div> : <div className="empty-state"><Search size={30}/><h3>No plates found</h3><p>Try a different search or browse all of the menu.</p><Button variant="outline" onClick={() => { setQuery(''); choose('all'); }}>Clear filters</Button></div>}</section></main>; }

function MenuCatalogue({ add }) { const params = new URLSearchParams(location.search); const [query, setQuery] = useState(''); const [category, setCategory] = useState(params.get('category') || 'all'); const [sort, setSort] = useState('featured'); const [loading, setLoading] = useState(false); const [filtersOpen, setFiltersOpen] = useState(false); const filtered = useMemo(() => { const list = MENU_ITEMS.filter((x) => (category === 'all' || x.category === category) && `${x.name} ${x.description} ${x.tag}`.toLowerCase().includes(query.toLowerCase())); return sort === 'low' ? [...list].sort((a,b) => a.price-b.price) : sort === 'high' ? [...list].sort((a,b) => b.price-a.price) : list; }, [category, query, sort]); const choose = (value) => { setLoading(true); setCategory(value); setFiltersOpen(false); setTimeout(() => setLoading(false), 350); }; const activeLabel = category === 'all' ? 'All plates' : MENU_CATEGORIES.find((x) => x.id === category)?.label || 'All plates'; return <main className="page menu-catalogue"><Intro eyebrow="The menu" title="Find your next favourite.">A considered catalogue of breakfasts, small chops, desserts, drinks and party packs. Everything is prepared to order in small batches.</Intro><section className="catalog"><div className="catalog-toolbar"><label className="search-field"><Search size={18}/><input aria-label="Search menu" placeholder="Search by name or ingredient" value={query} onChange={(e) => setQuery(e.target.value)}/></label><select value={sort} onChange={(e) => setSort(e.target.value)} aria-label="Sort menu"><option value="featured">Featured first</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select><button className="filter-toggle" onClick={() => setFiltersOpen(true)}><Search size={15}/> Filters <span>{activeLabel}</span></button></div><div className="catalog-filter-layout"><aside className="desktop-filters"><span className="eyebrow">Browse by category</span><button className={category === 'all' ? 'active' : ''} onClick={() => choose('all')}>All plates <span>{MENU_ITEMS.length}</span></button>{MENU_CATEGORIES.map((cat) => <button className={category === cat.id ? 'active' : ''} key={cat.id} onClick={() => choose(cat.id)}>{cat.label}<span>{MENU_ITEMS.filter((x) => x.category === cat.id).length}</span></button>)}</aside><div className="catalog-results"><div className="catalog-count"><span>{loading ? 'Finding something delicious...' : `${filtered.length} things worth sharing`}</span><span>{activeLabel} · Prices in Nigerian naira</span></div>{loading ? <div className="loading-state">Preparing the menu <span>•••</span></div> : filtered.length ? <div className="product-grid catalog-grid">{filtered.map((item) => <article className="product-card" key={item.id}><Link to={`/menu/${item.id}`} className="product-image"><img src={item.image} alt={item.name}/><span className="product-tag">{item.tag}</span></Link><div className="product-copy"><div className="product-meta"><span>{MENU_CATEGORIES.find((c) => c.id === item.category)?.label.split(' (')[0]}</span><span><Clock3 size={13}/> {item.prepTime}</span></div><h3>{item.name}</h3><p>{item.description}</p><div className="product-footer"><strong>{money(item.price)}</strong><div className="featured-actions"><Link to={`/menu/${item.id}`} className="text-link">View details</Link><button className="add-button" onClick={() => add(item)}><Plus size={17}/> Add</button></div></div></div></article>)}</div> : <div className="empty-state"><Search size={30}/><h3>No plates found</h3><p>Try a different search term or browse another category.</p><Button variant="outline" onClick={() => { setQuery(''); choose('all'); }}>Clear filters</Button></div>}</div></div>{filtersOpen && <div className="filter-overlay" role="dialog" aria-modal="true" aria-label="Menu filters"><div className="filter-drawer"><div className="filter-drawer-head"><div><span className="eyebrow">Menu filters</span><h2>Choose a category</h2></div><button onClick={() => setFiltersOpen(false)} aria-label="Close filters"><X size={20}/></button></div><button className={category === 'all' ? 'active' : ''} onClick={() => choose('all')}>All plates <span>{MENU_ITEMS.length}</span></button>{MENU_CATEGORIES.map((cat) => <button className={category === cat.id ? 'active' : ''} key={cat.id} onClick={() => choose(cat.id)}>{cat.label}<span>{MENU_ITEMS.filter((x) => x.category === cat.id).length}</span></button>)}</div></div>}</section></main>; }

function Detail({ id, add }) { const item = MENU_ITEMS.find((x) => x.id === id); const [qty, setQty] = useState(1); const [notes, setNotes] = useState(''); if (!item) return <NotFound title="That plate is off the menu."/>; return <main className="page detail-page"><Link to="/menu" className="back-link"><ChevronLeft size={16}/> Back to menu</Link><section className="detail"><div className="detail-image"><img src={item.image} alt={item.name}/><span className="product-tag">{item.tag}</span></div><div className="detail-copy"><span className="eyebrow">{MENU_CATEGORIES.find((c) => c.id === item.category)?.label}</span><h1>{item.name}</h1><strong className="detail-price">{money(item.price)}</strong><p>{item.description}</p><div className="detail-facts"><span><Clock3 size={17}/> Ready in {item.prepTime}</span><span><Sparkles size={17}/> Made to order</span></div><label className="field-label">Notes for the kitchen <span>Optional</span><textarea rows="3" placeholder="Any small details we should know?" value={notes} onChange={(e) => setNotes(e.target.value)}/></label><div className="detail-actions"><div className="quantity"><button onClick={() => setQty(Math.max(1, qty - 1))}><Minus size={15}/></button><span>{qty}</span><button onClick={() => setQty(qty + 1)}><Plus size={15}/></button></div><Button onClick={() => add(item, qty)}>Add to cart <ArrowRight size={17}/></Button></div><Link to="/menu" className="text-link">Continue browsing</Link></div></section></main>; }

function ProductDetails({ id, add }) { const item = MENU_ITEMS.find((x) => x.id === id); const [qty, setQty] = useState(1); const [notes, setNotes] = useState(''); const [activeImage, setActiveImage] = useState(item?.image); if (!item) return <NotFound title="That plate is off the menu."/>; const related = MENU_ITEMS.filter((x) => x.category === item.category && x.id !== item.id).slice(0, 3); const gallery = [item.image, '/assets/hero.jpg', '/assets/beverages.jpg']; const ingredients = item.category === 'breakfast' ? 'Buttermilk, seasonal fruit, free-range eggs, cultured butter and maple.' : item.category === 'chops' || item.category === 'party-packs' ? 'Seasoned pastry, fresh vegetables, herbs, spices and your choice of savoury filling.' : item.category === 'desserts' ? 'Vanilla cream, seasonal fruit, toasted granola and a touch of sweetness.' : 'Fresh fruit, herbs, citrus, ice and a house-made botanical blend.'; return <main className="page detail-page"><Link to="/menu" className="back-link"><ChevronLeft size={16}/> Back to menu</Link><section className="detail"><div className="detail-gallery"><div className="detail-image"><img src={activeImage} alt={item.name}/><span className="product-tag">{item.tag}</span></div><div className="gallery-thumbs">{gallery.map((image, index) => <button className={activeImage === image ? 'active' : ''} key={`${image}-${index}`} onClick={() => setActiveImage(image)}><img src={image} alt={`${item.name} view ${index + 1}`}/></button>)}</div></div><div className="detail-copy"><span className="eyebrow">{MENU_CATEGORIES.find((x) => x.id === item.category)?.label}</span><h1>{item.name}</h1><strong className="detail-price">{money(item.price)}</strong><p>{item.description}</p><div className="detail-facts"><span><Clock3 size={17}/> Ready in {item.prepTime}</span><span><Sparkles size={17}/> Made to order</span></div><div className="contents"><h3>What is inside</h3><p>{ingredients}</p></div><label className="field-label">Notes for the kitchen <span>Optional</span><textarea rows="3" placeholder="Any small details we should know?" value={notes} onChange={(e) => setNotes(e.target.value)}/></label><div className="detail-actions"><div className="quantity"><button onClick={() => setQty(Math.max(1, qty - 1))}><Minus size={15}/></button><span>{qty}</span><button onClick={() => setQty(qty + 1)}><Plus size={15}/></button></div><Button onClick={() => add(item, qty)}>Add to cart <ShoppingBag size={17}/></Button></div><Link to="/menu" className="text-link">Continue browsing <ArrowRight size={15}/></Link></div></section>{related.length > 0 && <section className="related section"><div className="section-heading"><div><span className="eyebrow">Keep exploring</span><h2>More from this table</h2></div></div><div className="product-grid">{related.map((product) => <ProductCard key={product.id} item={product} add={add}/>)}</div></section>}</main>; }

function Builder({ add }) { const [step, setStep] = useState(0); const [size, setSize] = useState(BOX_SIZES[1]); const [snack, setSnack] = useState(MENU_ITEMS.find((x) => x.id === 'chops-samosa')); const [drink, setDrink] = useState(MENU_ITEMS.find((x) => x.id === 'ref-chapman')); const [dessert, setDessert] = useState(MENU_ITEMS.find((x) => x.id === 'dessert-brownie-parfait')); const picks = [[BOX_SIZES, size, setSize], [MENU_ITEMS.filter((x) => ['chops','party-packs'].includes(x.category)).slice(0,6), snack, setSnack], [MENU_ITEMS.filter((x) => ['specialty','refreshers','coffee'].includes(x.category)).slice(0,6), drink, setDrink], [MENU_ITEMS.filter((x) => x.category === 'desserts'), dessert, setDessert]]; const current = picks[step]; const addBox = () => add({ id: `box-${size.id}`, name: size.name, price: size.price, image: '/assets/small_chops.jpg', tag: 'Custom box', description: `${size.name} with ${snack.name}, ${drink.name} and ${dessert.name}` }); return <main className="page builder-page"><Intro eyebrow="Build your box" title="A little bit of everything you love.">Choose the size, make your picks and add a custom Tchow moment to your cart.</Intro><div className="builder-layout"><section className="builder-main"><div className="progress">{['Box size','Small chop','A drink','Something sweet','Review'].map((label, i) => <div className={step >= i ? 'done' : ''} key={label}><span>{i+1}</span><label>{label}</label></div>)}</div>{step < 4 ? <><div className="builder-heading"><span className="eyebrow">Step {step+1} of 5</span><h2>{['Start with the right size.','Choose your savoury bite.','Add a little refreshment.','Finish on a sweet note.'][step]}</h2></div><div className="choice-grid">{current[0].map((item) => <button className={`choice-card ${current[1]?.id === item.id ? 'selected' : ''}`} key={item.id} onClick={() => current[2](item)}>{item.image && <img src={item.image} alt=""/>}<span><strong>{item.name}</strong><small>{item.desc || item.description}</small><b>{money(item.price)}</b></span>{current[1]?.id === item.id && <Check className="choice-check" size={18}/>}</button>)}</div><div className="builder-actions"><Button variant="ghost" onClick={() => setStep(Math.max(0, step-1))}><ChevronLeft size={16}/> Back</Button><Button onClick={() => setStep(step+1)}>Continue <ArrowRight size={16}/></Button></div></> : <div className="review"><span className="eyebrow">One last look</span><h2>Your box, your way.</h2>{[size,snack,drink,dessert].map((x) => <div className="review-row" key={x.id}><span>{x.name}</span><strong>{money(x.price)}</strong></div>)}<div className="review-total"><span>Box price</span><strong>{money(size.price)}</strong></div><div className="builder-actions"><Button variant="ghost" onClick={() => setStep(3)}><ChevronLeft size={16}/> Edit</Button><Button onClick={addBox}>Add box to cart <ShoppingBag size={16}/></Button></div></div>}</section><aside className="builder-summary"><span className="eyebrow">Your box</span><h3>{size.name}</h3><p>{size.desc}</p><div className="summary-list"><span>Base box <b>{money(size.price)}</b></span><span>{snack.name}<b>Included</b></span><span>{drink.name}<b>Included</b></span><span>{dessert.name}<b>Included</b></span></div><div className="summary-total"><span>Total</span><strong>{money(size.price)}</strong></div><button className="reset-link" onClick={() => setStep(0)}>Reset builder</button></aside></div></main>; }

function BoxBuilder({ add }) { const saved = store('tchow-box-progress', {}); const [step, setStep] = useState(saved.step || 0); const [size, setSize] = useState(BOX_SIZES.find((x) => x.id === saved.sizeId) || BOX_SIZES[1]); const [snack, setSnack] = useState(MENU_ITEMS.find((x) => x.id === saved.snackId) || MENU_ITEMS.find((x) => x.id === 'chops-samosa')); const [drink, setDrink] = useState(MENU_ITEMS.find((x) => x.id === saved.drinkId) || MENU_ITEMS.find((x) => x.id === 'ref-chapman')); const [dessert, setDessert] = useState(MENU_ITEMS.find((x) => x.id === saved.dessertId) || MENU_ITEMS.find((x) => x.id === 'dessert-brownie-parfait')); const [error, setError] = useState(''); const picks = [[BOX_SIZES, size, setSize], [MENU_ITEMS.filter((x) => ['chops','party-packs'].includes(x.category)).slice(0,6), snack, setSnack], [MENU_ITEMS.filter((x) => ['specialty','refreshers','coffee'].includes(x.category)).slice(0,6), drink, setDrink], [MENU_ITEMS.filter((x) => x.category === 'desserts'), dessert, setDessert]]; const current = picks[step]; const progress = { step, sizeId: size.id, snackId: snack.id, drinkId: drink.id, dessertId: dessert.id }; useEffect(() => localStorage.setItem('tchow-box-progress', JSON.stringify(progress)), [step, size, snack, drink, dessert]); const next = () => { if (step < 4 && !current?.[1]) { setError('Choose an option to continue.'); return; } setError(''); setStep(Math.min(4, step + 1)); }; const reset = () => { setStep(0); setSize(BOX_SIZES[1]); setSnack(null); setDrink(null); setDessert(null); setError(''); localStorage.removeItem('tchow-box-progress'); }; const addBox = () => { add({ id: `box-${size.id}-${Date.now()}`, name: size.name, price: size.price, image: '/assets/small_chops.jpg', tag: 'Custom box', description: `${size.name} with ${snack.name}, ${drink.name} and ${dessert.name}` }); localStorage.removeItem('tchow-box-progress'); }; const boxInfo = { mini: ['6 chops + 1 drink', 'Serves 1'], regular: ['12 chops + 1 drink + 1 parfait', 'Serves 1-2'], premium: ['20 chops + 2 drinks + 2 parfaits', 'Serves 2'], mega: ['40 chops + 4 drinks + 4 parfaits', 'Serves 4-6'] }; return <main className="page builder-page"><Intro eyebrow="Build your box" title="A little bit of everything you love.">Choose the size, make your picks and add a custom Tchow moment to your cart. Your progress is saved locally while you decide.</Intro><div className="builder-layout"><section className="builder-main"><div className="progress">{['Box size','Snacks','A drink','Dessert','Review'].map((label, i) => <button className={step >= i ? 'done' : ''} key={label} onClick={() => i <= step && setStep(i)}><span>{i + 1}</span><label>{label}</label></button>)}</div>{step < 4 ? <><div className="builder-heading"><span className="eyebrow">Step {step + 1} of 5</span><h2>{['Start with the right size.','Choose your savoury bite.','Add a little refreshment.','Finish on a sweet note.'][step]}</h2></div><div className="choice-grid">{current[0].map((item) => <button className={`choice-card ${current[1]?.id === item.id ? 'selected' : ''}`} key={item.id} onClick={() => { current[2](item); setError(''); }}>{item.image && <img src={item.image} alt=""/>}<span><strong>{item.name}</strong><small>{item.desc || item.description}</small>{step === 0 && <small>{boxInfo[item.id]?.[0]} · {boxInfo[item.id]?.[1]}</small>}<b>{money(item.price)}</b></span>{item.popular && <em className="popular-badge">Popular</em>}{current[1]?.id === item.id && <Check className="choice-check" size={18}/>}</button>)}</div>{error && <p className="builder-error" role="alert">{error}</p>}<div className="builder-actions"><Button variant="ghost" onClick={() => setStep(Math.max(0, step - 1))}><ChevronLeft size={16}/> Back</Button><Button onClick={next}>Continue <ArrowRight size={16}/></Button></div></> : <div className="review"><span className="eyebrow">One last look</span><h2>Your box, your way.</h2>{[[size,'Box size'],[snack,'Snack'],[drink,'Drink'],[dessert,'Dessert']].map(([x,label]) => <div className="review-row" key={label}><span>{label}<small>{x.name}</small></span><strong>{label === 'Box size' ? money(size.price) : 'Included'}</strong></div>)}<div className="review-total"><span>Box price</span><strong>{money(size.price)}</strong></div><div className="builder-actions"><Button variant="ghost" onClick={() => setStep(3)}><ChevronLeft size={16}/> Edit</Button><Button onClick={addBox}>Add box to cart <ShoppingBag size={16}/></Button></div></div>}</section><aside className="builder-summary"><span className="eyebrow">Live summary</span><h3>{size.name}</h3><p>{boxInfo[size.id]?.join(' · ')}. {size.desc}</p><div className="summary-list"><span>Base box <b>{money(size.price)}</b></span><span>{snack?.name || 'Choose a snack'}<b>{snack ? 'Included' : 'Required'}</b></span><span>{drink?.name || 'Choose a drink'}<b>{drink ? 'Included' : 'Required'}</b></span><span>{dessert?.name || 'Choose a dessert'}<b>{dessert ? 'Included' : 'Required'}</b></span></div><div className="summary-total"><span>Total</span><strong>{money(size.price)}</strong></div><button className="reset-link" onClick={reset}>Reset builder</button></aside></div></main>; }

function Cart({ cart, update }) { const items = Object.values(cart); const subtotal = items.reduce((sum, x) => sum + x.item.price * x.quantity, 0); return <main className="page cart-page"><Intro eyebrow="Your cart" title={items.length ? 'Almost ready to share.' : 'Your cart is waiting.'}>{items.length ? 'Review your picks before we move to the next step.' : 'There is always room for something delicious.'}</Intro>{items.length ? <div className="cart-layout"><section className="cart-list">{items.map(({item, quantity}) => <div className="cart-row" key={item.id}><img src={item.image} alt=""/><div className="cart-row-copy"><h3>{item.name}</h3><p>{item.tag}</p><strong>{money(item.price)}</strong></div><div className="quantity"><button onClick={() => update(item.id, quantity-1)}><Minus size={15}/></button><span>{quantity}</span><button onClick={() => update(item.id, quantity+1)}><Plus size={15}/></button></div><button className="remove" onClick={() => update(item.id, 0)}>Remove</button></div>)}<Link to="/menu" className="back-link"><ChevronLeft size={16}/> Keep browsing</Link></section><aside className="order-summary"><span className="eyebrow">Order summary</span><div><span>Subtotal</span><strong>{money(subtotal)}</strong></div><div><span>Delivery</span><span className="muted">Calculated at checkout</span></div><hr/><div className="summary-grand"><span>Total</span><strong>{money(subtotal)}</strong></div><Button to="/checkout">Continue to checkout <ArrowRight size={17}/></Button><p className="summary-note">Payment options are coming soon. This is a frontend preview.</p></aside></div> : <div className="empty-state cart-empty"><ShoppingBag size={36}/><h2>Nothing here yet.</h2><p>Start with a signature box or build something completely your own.</p><div><Button to="/menu">Explore menu</Button><Button to="/build-your-box" variant="outline">Build your box</Button></div></div>}</main>; }

function CartPage({ cart, update }) { const items = Object.values(cart); const subtotal = items.reduce((sum, x) => sum + x.item.price * x.quantity, 0); return <main className="page cart-page"><Intro eyebrow="Your cart" title={items.length ? 'Almost ready to share.' : 'Your cart is waiting.'}>{items.length ? 'Review your picks before we move to the next step.' : 'There is always room for something delicious.'}</Intro>{items.length ? <div className="cart-layout"><section className="cart-list">{items.map(({item, quantity}) => <div className="cart-row" key={item.id}><img src={item.image} alt={item.name}/><div className="cart-row-copy"><h3>{item.name}</h3><p>{item.tag}</p>{item.tag === 'Custom box' && <small className="custom-box-details">{item.description}</small>}<strong>{money(item.price)} <span className="unit-label">each</span></strong></div><div className="quantity"><button onClick={() => update(item.id, quantity - 1)} aria-label={`Decrease ${item.name}`}><Minus size={15}/></button><span>{quantity}</span><button onClick={() => update(item.id, quantity + 1)} aria-label={`Increase ${item.name}`}><Plus size={15}/></button></div><button className="remove" onClick={() => update(item.id, 0)}>Remove</button></div>)}<Link to="/menu" className="back-link"><ChevronLeft size={16}/> Continue shopping</Link></section><aside className="order-summary"><span className="eyebrow">Order summary</span><div><span>Order subtotal</span><strong>{money(subtotal)}</strong></div><div><span>Delivery estimate</span><span className="muted">Calculated at checkout</span></div><div className="delivery-placeholder"><Clock3 size={14}/> Same-day delivery slots shown at checkout.</div><hr/><div className="summary-grand"><span>Total</span><strong>{money(subtotal)}</strong></div><Button to="/checkout">Proceed to checkout <ArrowRight size={17}/></Button><p className="summary-note">Payment options are coming soon. This is a frontend preview.</p></aside></div> : <div className="empty-state cart-empty"><img src="/assets/small_chops.jpg" alt="A colourful Tchow food box"/><h2>Nothing here yet.</h2><p>Start with a signature box or build something completely your own.</p><div><Button to="/menu">Explore menu</Button><Button to="/build-your-box" variant="outline">Build your box</Button></div></div>}</main>; }

function Checkout({ cart }) { const [done, setDone] = useState(false); const [form, setForm] = useState({name:'',email:'',phone:'',address:'',area:'',agree:false}); const total = Object.values(cart).reduce((sum,x) => sum + x.item.price*x.quantity, 0); const submit = (e) => { e.preventDefault(); if (!form.name || !form.email || !form.phone || !form.address || !form.agree) return; const order = {number:`TC-${Date.now().toString().slice(-6)}`,...form,total}; localStorage.setItem('tchow-last-order', JSON.stringify(order)); setDone(true); }; if (done) return <Confirmation/>; return <main className="page checkout-page"><Intro eyebrow="Checkout" title="Let’s get this to your table.">Your details are saved locally for this frontend preview. No payment is processed here.</Intro><form className="checkout-layout" onSubmit={submit}><section className="form-card"><span className="eyebrow">1 / Your details</span><div className="form-grid">{[['Full name','name'],['Email address','email'],['Phone number','phone'],['Area','area']].map(([label,key]) => <label key={key}>{label}<input required type={key === 'email' ? 'email' : 'text'} value={form[key]} onChange={(e) => setForm({...form,[key]:e.target.value})}/></label>)}<label className="span-2">Delivery address<textarea required rows="3" value={form.address} onChange={(e) => setForm({...form,address:e.target.value})}/></label></div><span className="eyebrow payment-eyebrow">2 / Payment preview</span><div className="payment-options"><button type="button" disabled>Paystack <small>Coming soon</small></button><button type="button" disabled>Bank transfer <small>Coming soon</small></button><button type="button" disabled>WhatsApp confirmation <small>Coming soon</small></button></div><label className="checkbox"><input type="checkbox" checked={form.agree} onChange={(e) => setForm({...form,agree:e.target.checked})}/> I confirm these order details are correct.</label><Button type="submit">Continue to order confirmation <ArrowRight size={17}/></Button></section><aside className="order-summary"><span className="eyebrow">Your order</span>{Object.values(cart).map(({item,quantity}) => <div className="mini-line" key={item.id}><span>{quantity} × {item.name}</span><strong>{money(item.price*quantity)}</strong></div>)}<hr/><div className="summary-grand"><span>Total</span><strong>{money(total)}</strong></div></aside></form></main>; }
function CheckoutFrontend({ cart }) { const [form, setForm] = useState({name:'',email:'',phone:'',address:'',area:'',city:'Lagos',state:'Lagos',instructions:'',agree:false}); const [error, setError] = useState(''); const deliveryFee = Object.keys(cart).length ? 1500 : 0; const subtotal = Object.values(cart).reduce((sum,x) => sum + x.item.price*x.quantity, 0); const total = subtotal + deliveryFee; const updateField = (key, value) => setForm((current) => ({...current, [key]: value})); const submit = (e) => { e.preventDefault(); if (!form.name || !form.email || !form.phone || !form.address || !form.area || !form.city || !form.state || !form.agree) { setError('Please complete your contact, delivery and confirmation details.'); return; } localStorage.setItem('tchow-last-order', JSON.stringify({number:`TC-${Date.now().toString().slice(-6)}`,...form,subtotal,deliveryFee,total,items:Object.values(cart),status:'Received for review'})); history.pushState({}, '', '/order-confirmation'); dispatchEvent(new PopStateEvent('popstate')); }; return <main className="page checkout-page"><Intro eyebrow="Checkout" title="Let’s get this to your table.">This frontend preview records your order details locally. No payment is processed here.</Intro><form className="checkout-layout" onSubmit={submit} noValidate><section className="form-card"><span className="eyebrow">1 / Contact details</span><div className="form-grid"><label>Full name<input required value={form.name} onChange={(e) => updateField('name', e.target.value)}/></label><label>Email address<input required type="email" value={form.email} onChange={(e) => updateField('email', e.target.value)}/></label><label>Phone number<input required type="tel" value={form.phone} onChange={(e) => updateField('phone', e.target.value)}/></label></div><span className="eyebrow checkout-eyebrow">2 / Delivery details</span><div className="form-grid"><label className="span-2">Address<textarea required rows="3" value={form.address} onChange={(e) => updateField('address', e.target.value)}/></label><label>Area<input required value={form.area} onChange={(e) => updateField('area', e.target.value)}/></label><label>City<input required value={form.city} onChange={(e) => updateField('city', e.target.value)}/></label><label>State<select required value={form.state} onChange={(e) => updateField('state', e.target.value)}><option>Lagos</option><option>Ogun</option><option>Abuja</option><option>Other</option></select></label><label className="span-2">Delivery instructions <span className="optional">Optional</span><textarea rows="3" placeholder="Gate details, landmarks or timing notes" value={form.instructions} onChange={(e) => updateField('instructions', e.target.value)}/></label></div><span className="eyebrow payment-eyebrow">3 / Payment method preview</span><div className="payment-options"><button type="button" disabled>Paystack <small>Coming soon</small></button><button type="button" disabled>Bank transfer <small>Coming soon</small></button><button type="button" disabled>WhatsApp confirmation <small>Coming soon</small></button></div>{error && <p className="form-error" role="alert">{error}</p>}<label className="checkbox"><input type="checkbox" checked={form.agree} onChange={(e) => updateField('agree', e.target.checked)}/> I confirm that these order details are correct.</label><Button type="submit">Continue to order confirmation <ArrowRight size={17}/></Button></section><aside className="order-summary"><span className="eyebrow">Order summary</span>{Object.values(cart).map(({item,quantity}) => <div className="mini-line" key={item.id}><span>{quantity} × {item.name}</span><strong>{money(item.price*quantity)}</strong></div>)}<div><span>Subtotal</span><strong>{money(subtotal)}</strong></div><div><span>Estimated delivery fee</span><strong>{money(deliveryFee)}</strong></div><hr/><div className="summary-grand"><span>Total</span><strong>{money(total)}</strong></div><p className="summary-note">Payment is not collected in this frontend preview.</p></aside></form></main>; }

function Confirmation() { const order = store('tchow-last-order', {number:'TC-PREVIEW',name:'there',total:0,area:'your area',items:[]}); const itemRows = order.items || []; return <main className="page confirmation-page"><div className="confirmation-card"><div className="confirmation-icon"><Check size={30}/></div><span className="eyebrow">Order {order.number}</span><h1>We have your order details.</h1><p className="confirmation-lead">Thank you, {order.name.split(' ')[0] || 'there'}. Your order status is <strong>Received for review</strong>.</p><div className="confirmation-facts"><div><span>Customer</span><strong>{order.name || 'To be confirmed'}</strong></div><div><span>Delivery area</span><strong>{order.area || 'To be confirmed'}</strong></div><div><span>Estimated preparation</span><strong>20-30 minutes</strong></div></div><div className="confirmation-order"><div className="confirmation-order-head"><span className="eyebrow">Order summary</span><strong>{money(order.total)}</strong></div>{itemRows.length ? itemRows.map(({item,quantity}) => <div className="mini-line" key={item.id}><span>{quantity} × {item.name}</span><strong>{money(item.price * quantity)}</strong></div>) : <p className="muted">Your locally recorded order summary will appear here.</p>}</div><div className="next-steps"><span className="eyebrow">What happens next</span><p>Review your details, confirm availability, and prepare the next update. This preview does not send the order to a fulfilment team.</p></div><div className="preview-note"><Sparkles size={18}/><p>This frontend preview has recorded your order locally. Payment and fulfilment will be connected when the backend is implemented.</p></div><div className="hero-buttons"><Button to="/menu">Return to menu</Button><Button to="/account/orders" variant="outline">View account orders</Button></div></div></main>; }

function ContactForm({ investor = false }) { const [sent, setSent] = useState(false); const submit = (e) => { e.preventDefault(); localStorage.setItem(investor ? 'tchow-partnership-interest' : 'tchow-enquiry', JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))); setSent(true); }; if (sent) return <div className="success-card"><div className="confirmation-icon"><Check size={30}/></div><h2>{investor ? 'Interest recorded.' : 'Thanks for reaching out.'}</h2><p>{investor ? 'Your partnership interest has been recorded in this frontend preview. Formal review and communication workflows will be connected after the backend is implemented.' : 'Your enquiry has been stored in this frontend preview. A connected response workflow will be added with the backend.'}</p></div>; return <form className="wide-form" onSubmit={submit}><div className="form-grid"><label>Full name<input required name="name"/></label><label>Email address<input required type="email" name="email"/></label><label>Phone or WhatsApp<input required name="phone"/></label><label>{investor ? 'Organization' : 'Subject'}<input name="organization"/></label><label className="span-2">{investor ? 'Preferred partnership pathway' : 'How can we help?'}<select name="pathway" required defaultValue=""><option value="" disabled>Select one</option><option>Strategic partnership</option><option>Corporate catering</option><option>Revenue participation discussion</option><option>Equipment partnership</option><option>General enquiry</option></select></label><label className="span-2">Additional notes<textarea rows="5" name="notes"/></label><label className="checkbox span-2"><input required type="checkbox" name="consent"/> I understand this is a frontend preview and not a payment or investment commitment.</label></div><Button type="submit">{investor ? 'Submit partnership interest' : 'Save enquiry'} <ArrowRight size={17}/></Button></form>; }
function FormPage({ investor = false, catering = false }) { const title = investor ? 'Let’s explore what we could build together.' : catering ? 'Let us handle the spread.' : 'Tell us what you are planning.'; const eyebrow = investor ? 'Partnership interest application' : catering ? 'Corporate and private catering' : 'The concierge'; const copy = investor ? 'A thoughtful first step toward a strategic conversation.' : catering ? 'Share a few details about your event and we will shape a food experience around it.' : 'For orders, collaborations or anything else on your mind.'; return <main className="page form-page"><Intro eyebrow={eyebrow} title={title}>{copy}</Intro><ContactForm investor={investor}/></main>; }
function CateringPage() { const [sent, setSent] = useState(false); const [open, setOpen] = useState(0); const submit = (e) => { e.preventDefault(); localStorage.setItem('tchow-catering-enquiry', JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))); setSent(true); }; const services = [['Corporate breakfast','Fresh, thoughtful spreads for meetings and team mornings.'],['Small chops packages','Golden, crowd-friendly assortments for every kind of gathering.'],['Birthday events','Easy-to-share boxes that make the celebration feel personal.'],['Weddings and celebrations','Beautiful food moments shaped around your guest list.'],['Brand activations','Memorable bites and drinks for the moments people remember.'],['Office meetings','Neat, generous options that keep the room moving.'],['Private brunches','A relaxed Tchow table for the people closest to you.']]; const packages = [['Morning table','Breakfast platters, pastries, fruit and fresh juices.','From ₦8,500 per person'],['The small chops spread','Assorted small chops, dips and signature refreshers.','From ₦6,500 per person'],['Made-to-measure','A considered menu shaped around your event.','Enquire for a proposal']]; const faqs = ['How far ahead should I enquire?','Can you cater for dietary requirements?','Do you deliver and set up?']; if (sent) return <main className="page confirmation-page"><div className="success-card"><div className="confirmation-icon"><Check size={30}/></div><span className="eyebrow">Catering enquiry saved</span><h1>We have your details.</h1><p>Your catering enquiry has been recorded in this frontend preview. A connected response workflow will be added when the backend is implemented.</p><Button to="/">Return to Tchow</Button></div></main>; return <main className="page catering-page"><section className="catering-hero"><div><span className="eyebrow">Corporate and private catering</span><h1>Bring a little more joy to the table.</h1><p>Beautifully prepared breakfasts, small chops, desserts and drinks for gatherings that deserve thoughtful food.</p><Button to="#catering-enquiry">Start planning <ArrowRight size={17}/></Button></div><img src="/assets/hero.jpg" alt="A generous Tchow catering spread ready for sharing"/></section><section className="catering-section"><div className="section-heading"><div><span className="eyebrow">Ways we gather</span><h2>Catering for your kind of moment.</h2></div></div><div className="service-grid">{services.map(([title,copy]) => <article key={title}><span><Sparkles size={16}/></span><h3>{title}</h3><p>{copy}</p></article>)}</div></section><section className="catering-packages"><div><span className="eyebrow">A starting point</span><h2>Choose a direction.<br/><em>We will shape the rest.</em></h2><p>Our packages are a starting point, not a box. Tell us what you are hosting and we will help you make it feel like yours.</p></div><div className="package-list">{packages.map(([title,copy,price]) => <div key={title}><span className="package-number">0{packages.indexOf(packages.find((x) => x[0] === title)) + 1}</span><div><h3>{title}</h3><p>{copy}</p><strong>{price}</strong></div></div>)}</div></section><section className="planning-section"><div className="section-heading"><div><span className="eyebrow">How it works</span><h2>From first thought to full table.</h2></div></div><div className="planning-grid">{[['01','Tell us about it','Share your event, guest count, location and what matters to you.'],['02','Shape the menu','We work through a considered menu and practical options together.'],['03','Make it memorable','Your food is prepared, packed and ready for the moment.']].map(([number,title,copy]) => <div key={number}><span>{number}</span><h3>{title}</h3><p>{copy}</p></div>)}</div></section><section className="catering-form-section" id="catering-enquiry"><div className="form-intro"><span className="eyebrow">Start a conversation</span><h2>Tell us what you are planning.</h2><p>We will use these details to shape the right starting point. Nothing is sent to an administrator in this frontend preview.</p></div><form className="wide-form" onSubmit={submit}><div className="form-grid"><label>Full name<input required name="name"/></label><label>Organization<input name="organization"/></label><label>Email address<input required type="email" name="email"/></label><label>Phone number<input required type="tel" name="phone"/></label><label>Event type<select required name="eventType" defaultValue=""><option value="" disabled>Select event type</option>{services.map(([title]) => <option key={title}>{title}</option>)}</select></label><label>Event date<input required type="date" name="eventDate"/></label><label>Guest count<input required type="number" min="1" name="guestCount"/></label><label>Budget range<select required name="budget" defaultValue=""><option value="" disabled>Select a range</option><option>Under ₦100,000</option><option>₦100,000 - ₦250,000</option><option>₦250,000 - ₦500,000</option><option>₦500,000+</option></select></label><label className="span-2">Location<input required name="location" placeholder="Area, city or venue"/></label><label className="span-2">Additional requirements<textarea rows="5" name="requirements" placeholder="Dietary needs, timing, setup or anything else we should know"/></label></div><Button type="submit">Save catering enquiry <ArrowRight size={17}/></Button></form></section><section className="catering-faq"><span className="eyebrow">Catering FAQs</span>{faqs.map((question, i) => <div className={`faq ${open === i ? 'open' : ''}`} key={question}><button onClick={() => setOpen(open === i ? -1 : i)}>{question}<ChevronDown size={18}/></button>{open === i && <p>{['For larger events, two to four weeks gives us the best room to plan. We can sometimes accommodate shorter timelines.','Share your requirements in the enquiry and we will explore suitable options with you.','Delivery details and setup support depend on the event size and location; we will discuss this during planning.'][i]}</p>}</div>)}</section></main>; }

function AboutPage() { const values = [['01','Warmth','Food should make people feel looked after.'],['02','Curiosity','We stay open to new combinations, stories and ways to gather.'],['03','Consistency','Care is in the details, from the first message to the last bite.'],['04','Generosity','There should always be enough room for one more at the table.']]; const roadmap = [['Now','Curated collections','A focused menu of breakfasts, small chops, desserts and drinks for everyday moments.'],['Next','Bigger tables','Thoughtful catering and partnerships that bring Tchow to more gatherings.'],['Later','The Tchow Café','A warm physical space for food, conversation and a slower kind of day.']]; return <main className="page about-page"><Intro eyebrow="Our story" title="A table built around joy.">Tchow is a modern Nigerian food and lifestyle brand creating small, memorable moments through food. We believe the best experiences feel generous, personal and a little bit unexpected.</Intro><section className="about-story"><div className="about-story-copy"><span className="eyebrow">Where we began</span><h2>Everyday food deserves thoughtful attention.</h2><p>Tchow started with a simple idea: the food we share every day can carry the same care as a special occasion. We make breakfasts, small chops, desserts and drinks that give people a reason to pause, gather and enjoy the moment.</p><p>Our work is rooted in Nigerian hospitality and shaped by a love of considered details. From a well-packed box to a table prepared for a celebration, we want Tchow to feel like a warm welcome.</p></div><img src="/assets/hero.jpg" alt="A colourful Tchow table prepared for sharing"/></section><section className="founder-section"><img src="/assets/pancakes.jpg" alt="Tchow breakfast prepared with care"/><div><span className="eyebrow">A note from the founder</span><h2>Food is one of the ways we say, “you matter.”</h2><p>Tchow is being built with patience, curiosity and deep respect for the people who invite us to their tables. The goal is not to make food feel complicated. It is to make good moments feel a little easier to create.</p><strong>Founder, Tchow</strong></div></section><section className="mission-grid"><div><span className="eyebrow">Our mission</span><h2>Make memorable food moments more accessible.</h2><p>We create thoughtful food experiences that fit real life: a slow breakfast, an office meeting, a birthday table or a small celebration with the people who matter.</p></div><div><span className="eyebrow">Our vision</span><h2>Become a familiar place for gathering well.</h2><p>We are building toward a Tchow people can return to for food, hospitality and the feeling of being welcomed.</p></div></section><section className="values-section"><div className="section-heading"><div><span className="eyebrow">What guides us</span><h2>Values you can taste.</h2></div></div><div className="values-grid">{values.map(([number,title,copy]) => <div key={number}><span>{number}</span><h3>{title}</h3><p>{copy}</p></div>)}</div></section><section className="philosophy-grid"><article><span className="eyebrow">Product philosophy</span><h2>Simple ingredients. Considered combinations.</h2><p>We balance familiar Nigerian favourites with playful, modern touches. Every product should have a clear point of view, a satisfying texture and a reason to come back.</p></article><article><span className="eyebrow">Service philosophy</span><h2>Clarity is part of hospitality.</h2><p>We aim to communicate clearly, package carefully and make the experience feel calm from the first enquiry to the final delivery detail.</p></article></section><section className="roadmap-section"><div><span className="eyebrow">A measured path forward</span><h2>Growing with intention.</h2><p>Our roadmap is a direction, not a promise of fixed timelines. We will keep learning from the people who share their tables with us.</p></div><div className="roadmap-list">{roadmap.map(([phase,title,copy]) => <div key={phase}><span>{phase}</span><div><h3>{title}</h3><p>{copy}</p></div></div>)}</div></section><section className="cafe-vision"><img src="/assets/beverages.jpg" alt="Refreshing Tchow drinks for a future café table"/><div><span className="eyebrow">The future Tchow Café</span><h2>A place to stay a little longer.</h2><p>One day, Tchow may have a physical home: a welcoming café where breakfast stretches into conversation, a quick drink becomes a pause, and the table always feels open.</p><Button to="/contact">Start a conversation <ArrowRight size={17}/></Button></div></section></main>; }

function InvestorPage() { const [downloadMessage, setDownloadMessage] = useState(''); const overview = [['01','Business overview','Tchow creates curated food and beverage experiences for everyday moments, celebrations, workplaces and meaningful connections.'],['02','Current product model','A focused catalogue of breakfast collections, small chops, desserts, refreshers, coffee and custom boxes, supported by made-to-order preparation.'],['03','Who we serve','Individuals, families, office teams, event hosts, brands and organizations looking for warm, well-presented food experiences.']]; const channels = ['Direct menu orders and custom boxes','Corporate and private catering','Party packs and celebration collections','Future café and retail experiences']; const phases = [['Now','Strengthen the direct-to-customer menu and repeat ordering experience.'],['Next','Grow catering capability, operational consistency and selected strategic partnerships.'],['Future','Explore a physical Tchow Café and additional product formats with the right support.']]; const pathways = [['Strategic partnership','Commercial relationships that bring reach, capability or shared distribution.'],['Revenue participation discussion','A structured conversation tied to documented commercial performance and risk.'],['Equity discussion','Long-term ownership conversations subject to formal legal and financial review.'],['Equipment partnership','Support for kitchen, production or service equipment through documented arrangements.'],['Business advisory partnership','Practical expertise across operations, brand, hospitality, finance or growth.']]; return <main className="page investor-page"><section className="investor-hero"><div><span className="eyebrow">Investor relations</span><h1>A thoughtful brand, ready for its next chapter.</h1><p>Tchow is building a modern Nigerian food and lifestyle experience around good products, considered hospitality and responsible growth.</p><div className="hero-buttons"><Button to="/investors/apply">Submit partnership interest <ArrowRight size={17}/></Button><Button variant="outline" onClick={() => setDownloadMessage('Information pack download will be available when the investor document is connected.')}>Download information pack</Button></div>{downloadMessage && <p className="download-message" role="status">{downloadMessage}</p>}</div><img src="/assets/hero.jpg" alt="Tchow food and beverage spread prepared for a gathering"/></section><section className="investor-overview">{overview.map(([number,title,copy]) => <article key={number}><span>{number}</span><h2>{title}</h2><p>{copy}</p></article>)}</section><section className="investor-two-col"><div><span className="eyebrow">Revenue channels</span><h2>Several ways to create value.</h2><p>We are developing a balanced model across direct orders, gatherings and future physical experiences.</p></div><ul>{channels.map((channel) => <li key={channel}><Check size={16}/>{channel}</li>)}</ul></section><section className="growth-phases"><div><span className="eyebrow">Growth phases</span><h2>Build the foundation.<br/><em>Then widen the table.</em></h2></div><div>{phases.map(([phase,copy]) => <article key={phase}><span>{phase}</span><p>{copy}</p></article>)}</div></section><section className="funds-section"><div><span className="eyebrow">Use of funds</span><h2>Support the work behind the experience.</h2></div><div className="funds-grid">{['Kitchen and production capacity','People, training and operating systems','Packaging, delivery and service quality','Brand, digital and customer growth'].map((item, i) => <div key={item}><span>0{i+1}</span><strong>{item}</strong></div>)}</div></section><section className="pathways-section"><div className="section-heading"><div><span className="eyebrow">Partnership pathways</span><h2>Different partners, different ways to help.</h2></div></div><div className="pathways-grid">{pathways.map(([title,copy]) => <article key={title}><h3>{title}</h3><p>{copy}</p><Link to="/investors/apply" className="text-link">Discuss this pathway <ArrowRight size={15}/></Link></article>)}</div></section><section className="risk-section"><span className="eyebrow">Risk and transparency</span><h2>Good conversations need clear expectations.</h2><p>Any partnership discussion would require appropriate diligence, documentation and independent professional advice. Tchow does not make promises about returns, outcomes or timelines on this page.</p><div className="disclaimer">This page is for preliminary partnership interest only. It is not a public offer, financial advice, investment solicitation, or guarantee of returns.</div><p className="indicative-note">Any illustrative figures in future materials will be marked: “Indicative proposal subject to legal, financial, and commercial documentation.”</p></section></main>; }

function InvestorApplication() { const [sent, setSent] = useState(false); const [error, setError] = useState(''); const submit = (e) => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); if (!data.name || !data.email || !data.phone || !data.country || !data.pathway || !data.contribution || !data.timeline || !data.consent) { setError('Please complete the required fields and consent checkbox before continuing.'); return; } localStorage.setItem('tchow-partnership-application', JSON.stringify(data)); setSent(true); }; if (sent) return <main className="page confirmation-page"><div className="success-card"><div className="confirmation-icon"><Check size={30}/></div><span className="eyebrow">Partnership Interest Application</span><h1>Interest recorded.</h1><p>Your partnership interest has been recorded in this frontend preview. Formal review and communication workflows will be connected after the backend is implemented.</p><Button to="/investors">Return to Investor Relations</Button></div></main>; return <main className="page application-page"><Intro eyebrow="Partnership Interest Application" title="Start a thoughtful conversation.">Share a little about who you are, what you bring, and the kind of partnership you would like to explore.</Intro><form className="wide-form application-form" onSubmit={submit} noValidate><div className="form-grid"><label>Full name<input required name="name"/></label><label>Email address<input required type="email" name="email"/></label><label>Phone or WhatsApp number<input required type="tel" name="phone"/></label><label>Organization<input name="organization"/></label><label>Country<input required name="country"/></label><label>Preferred partnership pathway<select required name="pathway" defaultValue=""><option value="" disabled>Select a pathway</option><option>Strategic partnership</option><option>Revenue participation discussion</option><option>Equity discussion</option><option>Equipment partnership</option><option>Business advisory partnership</option></select></label><label>Expected capital or contribution range<select required name="contribution" defaultValue=""><option value="" disabled>Select a range</option><option>Skills or resources</option><option>Under ₦100,000</option><option>₦100,000 - ₦500,000</option><option>₦500,000 - ₦2,000,000</option><option>₦2,000,000+</option></select></label><label>Investment or partnership timeline<select required name="timeline" defaultValue=""><option value="" disabled>Select a timeline</option><option>Exploring</option><option>Within 3 months</option><option>3-6 months</option><option>6-12 months</option></select></label><label className="span-2">Strategic skills or resources<textarea required rows="4" name="skills" placeholder="What experience, access or resources would you bring?"/></label><label className="span-2">Additional notes<textarea rows="4" name="notes"/></label><label className="checkbox span-2"><input required type="checkbox" name="consent"/> I consent to Tchow storing this information for this frontend preview and understand that this is not a commitment or public offer.</label></div>{error && <p className="form-error" role="alert">{error}</p>}<div className="application-disclosures"><div><strong>Privacy explanation</strong><p>Your information is stored only in this browser for the prototype. It is not transmitted to Tchow or any third party.</p></div><div><strong>Risk disclaimer</strong><p>Any future partnership discussion is subject to diligence, formal documentation, risk review and independent professional advice. No outcome or return is guaranteed.</p></div></div><Button type="submit">Submit partnership interest <ArrowRight size={17}/></Button></form></main>; }

function ContactPage() { const [sent, setSent] = useState(false); const [error, setError] = useState(''); const submit = (e) => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); if (!data.name || !data.email || !data.subject || !data.message || !data.consent) { setError('Please complete the required fields and consent checkbox before saving your enquiry.'); return; } localStorage.setItem('tchow-contact-enquiry', JSON.stringify(data)); setSent(true); }; if (sent) return <main className="page confirmation-page"><div className="success-card"><div className="confirmation-icon"><Check size={30}/></div><span className="eyebrow">Enquiry saved</span><h1>Thanks for reaching out.</h1><p>Your enquiry has been stored in this frontend preview. A connected response workflow will be added when the backend is implemented.</p><Button to="/">Return to Tchow</Button></div></main>; return <main className="page contact-page"><section className="contact-hero"><div><span className="eyebrow">The Tchow concierge</span><h1>Let’s make something worth gathering for.</h1><p>Questions about the menu, a catering idea, or a partnership conversation? Start here and we will make the next step clear.</p><a className="button button-primary" href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noreferrer">Chat on WhatsApp <ArrowRight size={17}/></a></div><div className="contact-hero-image"><img src="/assets/beverages.jpg" alt="Tchow refreshments prepared for a gathering"/><span>Here when you need us.</span></div></section><section className="contact-channels"><article><span className="eyebrow">General enquiries</span><h2>hello@tchow.ng</h2><p>Menu questions, order guidance and anything else on your mind.</p><a href="mailto:hello@tchow.ng" className="text-link">Email the concierge <ArrowRight size={15}/></a></article><article><span className="eyebrow">Catering enquiries</span><h2>gather@tchow.ng</h2><p>Corporate breakfasts, private events and tables made for sharing.</p><a href="mailto:gather@tchow.ng" className="text-link">Email catering <ArrowRight size={15}/></a></article><article><span className="eyebrow">Partnership enquiries</span><h2>partners@tchow.ng</h2><p>Strategic, equipment, advisory and other thoughtful partnership conversations.</p><a href="/investors/apply" className="text-link">Submit interest <ArrowRight size={15}/></a></article></section><section className="contact-details"><div><span className="eyebrow">Phone and WhatsApp</span><h2>+234 800 000 0000</h2><p>Our WhatsApp number is configurable for the connected experience.</p><a className="text-link" href={`https://wa.me/${WHATSAPP_NUMBER}`} target="_blank" rel="noreferrer">Open WhatsApp <ArrowRight size={15}/></a></div><div><span className="eyebrow">Operating hours</span><h2>Tuesday - Sunday</h2><p>8:00am - 6:00pm<br/>Weekend breakfast: 7:00am - 12:00pm</p></div><div><span className="eyebrow">Where we are</span><h2>Lagos, Nigeria</h2><p>Kitchen and collection location details will be shared in the connected delivery experience.</p><span className="location-placeholder">Location map coming soon</span></div></section><section className="contact-form-section"><div><span className="eyebrow">Send a note</span><h2>How can we help?</h2><p>This form stores a mock enquiry locally. It does not send a message to the Tchow team yet.</p><Link to="/faq" className="text-link">Browse frequently asked questions <ArrowRight size={15}/></Link></div><form className="wide-form" onSubmit={submit} noValidate><div className="form-grid"><label>Full name<input required name="name"/></label><label>Email address<input required type="email" name="email"/></label><label className="span-2">Enquiry type<select required name="subject" defaultValue=""><option value="" disabled>Select one</option><option>General enquiry</option><option>Catering enquiry</option><option>Partnership enquiry</option><option>Order support</option></select></label><label className="span-2">Your message<textarea required rows="6" name="message"/></label><label className="checkbox span-2"><input required type="checkbox" name="consent"/> I understand this message is being saved locally for the frontend preview.</label></div>{error && <p className="form-error" role="alert">{error}</p>}<Button type="submit">Save enquiry <ArrowRight size={17}/></Button></form></section></main>; }
function Admin({ section = 'dashboard' }) { if (section === 'orders') return <AdminOrders/>; if (section === 'catering') return <AdminCatering/>; const labels = { dashboard: ['Operations', 'A clear view of the day.'], orders: ['Order management', 'Keep every order moving.'], menu: ['Menu management', 'Keep the catalogue current.'], catering: ['Catering enquiries', 'Plan the next great table.'], investors: ['Partnership applications', 'Review interest responsibly.'], settings: ['Settings', 'Shape the frontend preview.'] }; const [eyebrow, title] = labels[section] || labels.dashboard; const stats = [['Orders today','18'],['Pending orders','07'],['Catering enquiries','04'],['Partnership applications','03'],['Estimated sales','₦186,500']]; const recent = [['TC-42108','Amaka Okafor','The Tchow Box','Received for review'],['TC-42107','Dami Adeyemi','Weekend Bliss Platter','Preparing'],['TC-42106','Nneka James','Classic Party Pack','Ready for dispatch']]; return <main className="admin-page"><aside className="admin-sidebar"><div className="wordmark">TCHOW<span>.</span></div><span className="admin-label">Operations preview</span>{Object.keys(labels).map((key) => <Link key={key} to={key === 'dashboard' ? '/admin' : `/admin/${key}`} className={section === key ? 'active' : ''}>{labels[key][0]}</Link>)}<Link to="/">Exit preview <ArrowRight size={14}/></Link></aside><div className="admin-workspace"><header className="admin-topbar"><div><span className="eyebrow">Internal operations</span><strong>{eyebrow}</strong></div><div className="admin-controls"><label>Period<select defaultValue="today"><option value="today">Today</option><option>This week</option><option>This month</option></select></label><span className="mock-pill">Mock data</span></div></header><div className="admin-content"><div className="admin-banner"><span className="eyebrow">Frontend-only internal preview</span><strong>Mock data only</strong></div><Intro eyebrow={eyebrow} title={title}>Authentication, database, notifications and backend workflows are not connected.</Intro><div className="admin-stats">{stats.map(([label,value]) => <div key={label}><span>{label}</span><strong>{value}</strong><small>Mock data</small></div>)}</div><div className="admin-panels"><section className="admin-table"><div className="section-heading"><div><span className="eyebrow">Latest activity</span><h2>Recent orders</h2></div><Link to="/admin/orders" className="text-link">View all <ArrowRight size={15}/></Link></div>{recent.map(([id,name,item,status]) => <div className="admin-row" key={id}><span><strong>{id}</strong><small>{name}</small></span><span>{item}</span><span className="status">{status}</span></div>)}</section><section className="admin-side-panel"><span className="eyebrow">Needs attention</span><h2>Product availability</h2>{['Weekend Bliss Breakfast Platter','Tchow Sunset Cooler','Classic Party Pack'].map((item, i) => <div className="availability-row" key={item}><span>{item}</span><b className={i === 1 ? 'low-stock' : ''}>{i === 1 ? 'Low stock' : 'Available'}</b></div>)}<Link to="/admin/menu" className="text-link">Manage menu <ArrowRight size={15}/></Link></section></div><div className="admin-lower"><section className="admin-side-panel"><span className="eyebrow">Catering enquiries</span><h2>4 open conversations</h2><p>Corporate breakfasts, private celebrations and office tables awaiting review.</p><Link to="/admin/catering" className="text-link">Review catering <ArrowRight size={15}/></Link></section><section className="admin-side-panel"><span className="eyebrow">Partnership interest</span><h2>3 applications</h2><p>New and under-review partnership conversations in the local preview.</p><Link to="/admin/investors" className="text-link">Review applications <ArrowRight size={15}/></Link></section><section className="admin-side-panel"><span className="eyebrow">Activity timeline</span><div className="timeline"><p><b>09:42</b> New order received for review</p><p><b>09:18</b> Catering enquiry saved locally</p><p><b>08:55</b> Menu availability updated</p></div></section></div></div></div></main>; }
function Profile() { const [saved, setSaved] = useState(false); const [error, setError] = useState(''); const profile = store('tchow-profile', {}); const submit = (e) => { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); if (!data.name || !data.email || !data.phone || !data.address) { setSaved(false); setError('Please complete your name, email, phone number and delivery address.'); return; } localStorage.setItem('tchow-profile', JSON.stringify(data)); setError(''); setSaved(true); }; return <main className="page form-page"><Intro eyebrow="Your account / profile" title="Your details, your way.">Save your contact, delivery and dietary preferences locally for this frontend preview.</Intro><form className="wide-form profile-form" onSubmit={submit} noValidate><div className="form-grid"><label>Full name<input required name="name" defaultValue={profile.name || ''}/></label><label>Email address<input required type="email" name="email" defaultValue={profile.email || ''}/></label><label>Phone number<input required type="tel" name="phone" defaultValue={profile.phone || ''}/></label><label>Preferred communication<select name="communication" defaultValue={profile.communication || 'Email'}><option>Email</option><option>Phone</option><option>WhatsApp</option></select></label><label className="span-2">Default delivery address<textarea required rows="3" name="address" defaultValue={profile.address || ''}/></label><label className="span-2">Dietary notes <span className="optional">Optional</span><textarea rows="4" name="dietaryNotes" defaultValue={profile.dietaryNotes || ''} placeholder="Allergies, preferences or things to keep in mind"/></label></div>{error && <p className="form-error" role="alert">{error}</p>}{saved && <p className="form-success" role="status"><Check size={15}/> Profile changes saved locally.</p>}<Button type="submit">Save changes <Check size={16}/></Button></form></main>; }
function CustomerOrders() { const latest = store('tchow-last-order', null); const [selected, setSelected] = useState(null); const mockOrders = [{number:'TC-42108',date:'12 Aug 2026',items:'The Tchow Box · 2 items',total:13000,status:'Received for review'}, {number:'TC-42091',date:'03 Aug 2026',items:'Weekend Bliss Breakfast Platter',total:8500,status:'Preparing'}, {number:'TC-42044',date:'21 Jul 2026',items:'Classic Party Pack · 40 pieces',total:14000,status:'Completed'}]; const orders = latest ? [{number:latest.number,date:'Today',items:latest.items?.map((x) => `${x.quantity} × ${x.item.name}`).join(', ') || 'Local order',total:latest.total,status:latest.status || 'Received for review',details:latest}, ...mockOrders] : mockOrders; return <main className="page orders-page"><Intro eyebrow="Your account / orders" title="Order history.">A clear view of local preview orders and their current mock status.</Intro><div className="orders-list">{orders.map((order) => <div className="order-card" key={order.number}><div><strong>{order.number}</strong><span>{order.date}</span></div><p>{order.items}</p><strong>{money(order.total)}</strong><span className={`status-badge status-${order.status.toLowerCase().replaceAll(' ','-')}`}>{order.status}</span><button className="button button-outline order-view" onClick={() => setSelected(order)}>View order</button></div>)}</div>{selected && <div className="drawer-overlay" role="presentation" onClick={() => setSelected(null)}><aside className="order-drawer" role="dialog" aria-modal="true" aria-labelledby="order-drawer-title" onClick={(e) => e.stopPropagation()}><button className="drawer-close" onClick={() => setSelected(null)} aria-label="Close order details"><X size={20}/></button><span className="eyebrow">Order details</span><h2 id="order-drawer-title">{selected.number}</h2><span className={`status-badge status-${selected.status.toLowerCase().replaceAll(' ','-')}`}>{selected.status}</span><div className="drawer-details"><div><span>Date</span><strong>{selected.date}</strong></div><div><span>Items</span><strong>{selected.items}</strong></div><div><span>Total</span><strong>{money(selected.total)}</strong></div><div><span>Payment</span><strong>Coming soon</strong></div></div><div className="preview-note"><Sparkles size={18}/><p>This is mock order data for the frontend preview. Payment and fulfilment are not connected.</p></div></aside></div>}</main>; }

function Account({ orders = false }) { const order = store('tchow-last-order', null); const [customer, setCustomer] = useState(() => store('tchow-customer', null)); const [email, setEmail] = useState(''); const signIn = (event) => { event.preventDefault(); if (!email) return; const next = { name: email.split('@')[0], email }; localStorage.setItem('tchow-customer', JSON.stringify(next)); setCustomer(next); }; if (orders) return <CustomerOrders/>; if (!customer) return <main className="page account-page"><div className="account-preview"><span className="eyebrow">Your account</span><h1>Keep your Tchow moments close.</h1><p>Sign in to see recent orders, saved delivery details and custom boxes. This is a frontend preview, not real authentication.</p><form className="account-signin" onSubmit={signIn}><label>Email address<input required type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com"/></label><label>Password<input required type="password" placeholder="••••••••"/></label><Button type="submit">Continue <ArrowRight size={17}/></Button></form><button className="create-account" onClick={() => setEmail('new@tchow.ng')}>Create an account preview</button></div></main>; return <main className="page account-page"><div className="account-header"><div><span className="eyebrow">Your account</span><h1>Hello, {customer.name}.</h1><p>Your Tchow details and moments, in one place.</p></div><nav className="account-nav"><Link to="/account">Overview</Link><Link to="/account/orders">Orders</Link><Link to="/account/profile">Profile</Link></nav></div><div className="account-dashboard"><div className="account-card account-welcome"><span className="eyebrow">Account summary</span><h2>Ready for your next table?</h2><p>{customer.email}</p><Button to="/menu">Explore the menu <ArrowRight size={17}/></Button></div><div className="account-card"><span className="eyebrow">Recent orders</span>{order ? <><strong>{order.number}</strong><p>Received for review · {money(order.total)}</p><Link to="/account/orders" className="text-link">View all orders <ArrowRight size={15}/></Link></> : <><p>No local orders yet.</p><Link to="/menu" className="text-link">Start an order <ArrowRight size={15}/></Link></>}</div><div className="account-card"><span className="eyebrow">Saved delivery details</span><strong>Lagos, Nigeria</strong><p>Save a default address in your profile for faster checkout later.</p><Link to="/account/profile" className="text-link">Edit details <ArrowRight size={15}/></Link></div><div className="account-card"><span className="eyebrow">Saved custom boxes</span><strong>Your next box starts here.</strong><p>Build a combination for breakfast, gifting or sharing.</p><Link to="/build-your-box" className="text-link">Build a box <ArrowRight size={15}/></Link></div></div></main>; }
function NotFound({ title = 'This page wandered off.' }) { return <main className="page not-found"><span className="eyebrow">404</span><h1>{title}</h1><p>Let’s get you back to the good stuff.</p><div><Button to="/">Return home</Button><Button to="/menu" variant="outline">Explore menu</Button></div></main>; }

export default function App() { const go = useRouter(); const { cart, add, update, count } = useCart(); const [toast,setToast] = useState(''); const addToCart = (item, quantity=1) => { add(item, quantity); setToast(`${item.name} added to cart`); setTimeout(() => setToast(''), 2200); }; const path = location.pathname; let page; if (path === '/') page=<DatabaseHome add={addToCart}/>; else if (path === '/menu') page=<DatabaseMenu add={addToCart}/>; else if (path.startsWith('/menu/')) page=<DatabaseProductDetail id={path.split('/')[2]} add={addToCart}/>; else if (path === '/build-your-box') page=<DatabaseBoxBuilder add={addToCart}/>; else if (path === '/cart') page=<CartPage cart={cart} update={update}/>; else if (path === '/checkout') page=<AuthGate><DatabaseCheckout cart={cart}/></AuthGate>; else if (path === '/order-confirmation') page=<AuthGate><DatabaseOrderConfirmation/></AuthGate>; else if (path === '/payment-status') page=<PaymentStatus/>; else if (path === '/catering') page=<DatabaseCatering/>; else if (path === '/contact') page=<DatabaseContact/>; else if (path === '/investors/apply') page=<DatabasePartnership/>; else if (path === '/about') page=<AboutPage/>; else if (path === '/investors') page=<InvestorPage/>; else if (path === '/faq') page=<FAQPage/>; else if (path.startsWith('/account/orders/')) page=<AuthGate><DatabaseOrderConfirmation/></AuthGate>; else if (path === '/account/orders') page=<AuthGate><AccountOrders/></AuthGate>; else if (path === '/account/profile') page=<AuthGate><AccountProfile/></AuthGate>; else if (path === '/account') page=<AuthGate><AccountHome/></AuthGate>; else if (path === '/admin/orders') page=<StaffGate><DatabaseAdminOrders/></StaffGate>; else if (path === '/admin/menu') page=<StaffGate><DatabaseAdminMenu/></StaffGate>; else if (path === '/admin/catering') page=<StaffGate><DatabaseAdminEnquiries kind="catering"/></StaffGate>; else if (path === '/admin/investors') page=<StaffGate><DatabaseAdminEnquiries kind="partnership"/></StaffGate>; else if (path === '/admin/settings') page=<StaffGate><DatabaseAdminSettings/></StaffGate>; else if (path.startsWith('/admin')) page=<StaffGate>{path === '/admin' ? <DatabaseAdminOverview/> : <Admin section={path.split('/')[2] || 'dashboard'}/>}</StaffGate>; else if (path === '/signin') page=<AuthPage mode="signin"/>; else if (path === '/register') page=<AuthPage mode="register"/>; else if (path === '/forgot-password') page=<AuthPage mode="forgot"/>; else if (path === '/reset-password') page=<AuthPage mode="reset"/>; else if (path === '/terms') page=<LegalPage kind="terms"/>; else if (path === '/privacy') page=<LegalPage kind="privacy"/>; else if (path === '/404') page=<Error404/>; else page=<Error404/>; return <div className="app-shell"><Header count={count}/>{page}<Footer/>{toast && <div className="toast"><Check size={16}/>{toast}</div>}</div>; }
